insert into public.glossary_terms (id, term, category, definition, coach_note, example, related_terms, source_name, source_url, raw_json, updated_at) values
  ('afk', 'afk', 'Gaming Chat', 'Away from keyboard. The player is not currently active.', 'Away from keyboard.', 'our healer is afk', '["Chat","Status"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"afk","term":"afk","category":"Gaming Chat","definition":"Away from keyboard. The player is not currently active.","coachNote":"Away from keyboard.","example":"our healer is afk","relatedTerms":["Chat","Status"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('anchor-hero', 'Anchor Hero', 'Team-Up', 'The hero required for a Team-Up to become active. The anchor usually receives a stat bonus while enabling one or more allies to gain Team-Up effects.', 'Check anchor requirements before building around a Team-Up. If the anchor swaps, the Team-Up plan disappears.', 'Doctor Strange can anchor Arcane Order for Scarlet Witch and Magik.', '["Team-Up","Secondary Hero","Team-Up Ability"]'::jsonb, 'Marvel Rivals Wiki - Team-Ups', 'https://marvelrivals.fandom.com/wiki/Team-Ups', '{"id":"anchor-hero","term":"Anchor Hero","category":"Team-Up","definition":"The hero required for a Team-Up to become active. The anchor usually receives a stat bonus while enabling one or more allies to gain Team-Up effects.","coachNote":"Check anchor requirements before building around a Team-Up. If the anchor swaps, the Team-Up plan disappears.","example":"Doctor Strange can anchor Arcane Order for Scarlet Witch and Magik.","relatedTerms":["Team-Up","Secondary Hero","Team-Up Ability"],"sourceName":"Marvel Rivals Wiki - Team-Ups","sourceUrl":"https://marvelrivals.fandom.com/wiki/Team-Ups"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('angle', 'Angle', 'Marvel Rivals', 'A position or line of attack that changes who can see, shoot, heal, or threaten whom. In Marvel Rivals coaching, an angle is usually about creating pressure from a useful direction while still having cover or an escape path.', 'A position or line of attack that creates pressure from a useful direction.', 'Taking the balcony angle lets Hela pressure the enemy backline while her team walks main.', '["Marvel Rivals","Positioning","Sightline","Off Angle","Cover"]'::jsonb, 'Coach definition informed by Marvel Rivals positioning terms', '/glossary', '{"id":"angle","term":"Angle","category":"Marvel Rivals","definition":"A position or line of attack that changes who can see, shoot, heal, or threaten whom. In Marvel Rivals coaching, an angle is usually about creating pressure from a useful direction while still having cover or an escape path.","coachNote":"A position or line of attack that creates pressure from a useful direction.","example":"Taking the balcony angle lets Hela pressure the enemy backline while her team walks main.","relatedTerms":["Marvel Rivals","Positioning","Sightline","Off Angle","Cover"],"sourceName":"Coach definition informed by Marvel Rivals positioning terms","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('annihilation', 'Annihilation', 'Game Mode', 'A large-team mode where two sides score by earning eliminations, with a target score or timer deciding the winner.', 'In elimination-heavy modes, survival and cleanup matter more than slow objective posture. Avoid feeding points through isolated duels.', '18 vs. 18 Annihilation rewards teams for reaching the kill target before time expires.', '["PvP","Elimination","Final Hit","Team Fight"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"annihilation","term":"Annihilation","category":"Game Mode","definition":"A large-team mode where two sides score by earning eliminations, with a target score or timer deciding the winner.","coachNote":"In elimination-heavy modes, survival and cleanup matter more than slow objective posture. Avoid feeding points through isolated duels.","example":"18 vs. 18 Annihilation rewards teams for reaching the kill target before time expires.","relatedTerms":["PvP","Elimination","Final Hit","Team Fight"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('anti-heal', 'Anti-heal', 'Competitive Gaming', 'Reducing or blocking the healing a target can receive.', 'When a target is anti-healed, commit damage now: their healers cannot save them until it wears off.', 'He''s anti''d, he can''t get healed, finish him.', '["Healing Reduction","Strategist","Burst"]'::jsonb, 'Overlay glossary seed (MetaBot.gg and Dot Esports terminology)', '/glossary', '{"id":"anti-heal","term":"Anti-heal","category":"Competitive Gaming","definition":"Reducing or blocking the healing a target can receive.","coachNote":"When a target is anti-healed, commit damage now: their healers cannot save them until it wears off.","example":"He''s anti''d, he can''t get healed, finish him.","relatedTerms":["Healing Reduction","Strategist","Burst"],"sourceName":"Overlay glossary seed (MetaBot.gg and Dot Esports terminology)","sourceUrl":"/glossary"}'::jsonb, '2026-10-26 23:38:59+00'::timestamptz),
  ('aoe', 'aoe', 'Competitive Gaming', 'Area of effect. Describes damage, healing, or control that affects an area instead of one target.', 'Area of effect.', 'avoid the aoe', '["Ability","Combat"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"aoe","term":"aoe","category":"Competitive Gaming","definition":"Area of effect. Describes damage, healing, or control that affects an area instead of one target.","coachNote":"Area of effect.","example":"avoid the aoe","relatedTerms":["Ability","Combat"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('arcade', 'Arcade', 'Game Mode', 'A casual hub for alternate Marvel Rivals modes that use different rules from the standard objective queues.', 'Arcade can sharpen mechanics and hero comfort, but always check the mode rules before judging whether a play was correct.', 'Conquest and Doom Match are examples of Arcade-style modes.', '["Conquest","Doom Match","Free Fight","PvP"]'::jsonb, 'Marvel Rivals Wiki - Game Modes', 'https://marvelrivals.fandom.com/wiki/Game_Modes', '{"id":"arcade","term":"Arcade","category":"Game Mode","definition":"A casual hub for alternate Marvel Rivals modes that use different rules from the standard objective queues.","coachNote":"Arcade can sharpen mechanics and hero comfort, but always check the mode rules before judging whether a play was correct.","example":"Conquest and Doom Match are examples of Arcade-style modes.","relatedTerms":["Conquest","Doom Match","Free Fight","PvP"],"sourceName":"Marvel Rivals Wiki - Game Modes","sourceUrl":"https://marvelrivals.fandom.com/wiki/Game_Modes"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('area-healer', 'Area Healer', 'Role', 'Also called an AoE healer, a healer whose abilities restore health to multiple allies inside an area, field, beam path, or other shared zone.', 'Area healing gains value when the team groups without stacking recklessly. Spread-out flyers and flankers can force the healer to choose which cluster receives support.', 'The team groups inside the healing field so the area healer can stabilize several allies at once.', '["AoE","Sustain Healer","Brawl","Positioning"]'::jsonb, 'MarvelRivals.gg grouped-healing Strategist guides', 'https://marvelrivals.gg/jeff-the-land-shark-guide/', '{"id":"area-healer","term":"Area Healer","category":"Role","definition":"Also called an AoE healer, a healer whose abilities restore health to multiple allies inside an area, field, beam path, or other shared zone.","coachNote":"Area healing gains value when the team groups without stacking recklessly. Spread-out flyers and flankers can force the healer to choose which cluster receives support.","example":"The team groups inside the healing field so the area healer can stabilize several allies at once.","relatedTerms":["AoE","Sustain Healer","Brawl","Positioning"],"sourceName":"MarvelRivals.gg grouped-healing Strategist guides","sourceUrl":"https://marvelrivals.gg/jeff-the-land-shark-guide/"}'::jsonb, '2026-07-27 08:06:06+00'::timestamptz),
  ('assist', 'Assist', 'Combat', 'Credit for helping an ally secure an elimination through support actions such as healing, slowing, boosting, or other utility.', 'In Marvel Rivals, assists reward meaningful support value. Strategists can contribute heavily without being the final damage source.', 'Healing an ally while they finish a target can contribute to an assist.', '["Strategist","Utility Build","Elimination","Support"]'::jsonb, 'Polygon - How to get assists in Marvel Rivals', 'https://www.polygon.com/marvel-rivals-guide/510849/assists-how-to-get', '{"id":"assist","term":"Assist","category":"Combat","definition":"Credit for helping an ally secure an elimination through support actions such as healing, slowing, boosting, or other utility.","coachNote":"In Marvel Rivals, assists reward meaningful support value. Strategists can contribute heavily without being the final damage source.","example":"Healing an ally while they finish a target can contribute to an assist.","relatedTerms":["Strategist","Utility Build","Elimination","Support"],"sourceName":"Polygon - How to get assists in Marvel Rivals","sourceUrl":"https://www.polygon.com/marvel-rivals-guide/510849/assists-how-to-get"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('backline', 'Backline', 'Coach Term', 'The safer rear area of a team formation where Strategists and long-range heroes often play.', 'Backline players should keep escape routes and line of sight to allies. Frontline players should notice when the backline is pressured.', 'A Luna Snow positioned behind Groot and Punisher is playing in the backline.', '["Peeling","Dive","Flanking"]'::jsonb, 'Coach definition informed by Marvel Rivals role terminology', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"backline","term":"Backline","category":"Coach Term","definition":"The safer rear area of a team formation where Strategists and long-range heroes often play.","coachNote":"Backline players should keep escape routes and line of sight to allies. Frontline players should notice when the backline is pressured.","example":"A Luna Snow positioned behind Groot and Punisher is playing in the backline.","relatedTerms":["Peeling","Dive","Flanking"],"sourceName":"Coach definition informed by Marvel Rivals role terminology","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('bonus-health', 'Bonus Health', 'Status Effect', 'Temporary extra health granted by an ability, buff, or effect, increasing how much damage a hero can survive before being eliminated.', 'Treat bonus health as a timing resource. Push while it is active, then reset before the extra durability disappears.', 'A Vanguard may gain bonus health before committing into the enemy frontline.', '["Sustain","Damage Reduction","Vanguard","Buff"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"bonus-health","term":"Bonus Health","category":"Status Effect","definition":"Temporary extra health granted by an ability, buff, or effect, increasing how much damage a hero can survive before being eliminated.","coachNote":"Treat bonus health as a timing resource. Push while it is active, then reset before the extra durability disappears.","example":"A Vanguard may gain bonus health before committing into the enemy frontline.","relatedTerms":["Sustain","Damage Reduction","Vanguard","Buff"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('brawl', 'Brawl', 'Positioning', 'A close-range teamfight style built around durable heroes, sustain, and forcing the enemy to fight in your effective range.', 'Brawl comps want short paths, cover, and committed pushes. Do not slowly walk through long poke sightlines.', 'Hulk, The Thing, Wolverine, and Rogue are examples of heroes that can support brawl plans.', '["Sustain","Tank","Choke"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"brawl","term":"Brawl","category":"Positioning","definition":"A close-range teamfight style built around durable heroes, sustain, and forcing the enemy to fight in your effective range.","coachNote":"Brawl comps want short paths, cover, and committed pushes. Do not slowly walk through long poke sightlines.","example":"Hulk, The Thing, Wolverine, and Rogue are examples of heroes that can support brawl plans.","relatedTerms":["Sustain","Tank","Choke"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('brb', 'brb', 'Internet Slang', 'Be right back. Used when someone steps away briefly.', 'Be right back.', 'brb one sec', '["Chat","Away"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"brb","term":"brb","category":"Internet Slang","definition":"Be right back. Used when someone steps away briefly.","coachNote":"Be right back.","example":"brb one sec","relatedTerms":["Chat","Away"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('buff', 'buff', 'Competitive Gaming', 'A balance change or effect that makes a character, weapon, ability, or strategy stronger.', 'A change or effect that makes something stronger.', 'the patch buffed tanks', '["Balance","Patch"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"buff","term":"buff","category":"Competitive Gaming","definition":"A balance change or effect that makes a character, weapon, ability, or strategy stronger.","coachNote":"A change or effect that makes something stronger.","example":"the patch buffed tanks","relatedTerms":["Balance","Patch"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('burst-healer', 'Burst Healer', 'Role', 'A healer who can restore a large amount of health in a short window, often by spending a cooldown, charge, or limited resource.', 'Save burst healing for real damage spikes. Spending it on minor chip damage can leave no answer when an ally suddenly becomes critical.', 'The burst healer holds a charge to rescue a Vanguard when focused damage lands.', '["Primary Healer","Sustain Healer","Cooldown Trade","Burst"]'::jsonb, 'PC Gamer Marvel Rivals healer and team-composition analysis', 'https://www.pcgamer.com/games/third-person-shooter/marvel-rivals-tier-list-best-characters/', '{"id":"burst-healer","term":"Burst Healer","category":"Role","definition":"A healer who can restore a large amount of health in a short window, often by spending a cooldown, charge, or limited resource.","coachNote":"Save burst healing for real damage spikes. Spending it on minor chip damage can leave no answer when an ally suddenly becomes critical.","example":"The burst healer holds a charge to rescue a Vanguard when focused damage lands.","relatedTerms":["Primary Healer","Sustain Healer","Cooldown Trade","Burst"],"sourceName":"PC Gamer Marvel Rivals healer and team-composition analysis","sourceUrl":"https://www.pcgamer.com/games/third-person-shooter/marvel-rivals-tier-list-best-characters/"}'::jsonb, '2026-07-27 08:06:05+00'::timestamptz),
  ('bussing', 'Bussing', 'Competitive Gaming', 'Intentionally teaming up with a cheater so the cheater can carry you to wins and artificially raise your rank. Simply being matched with a cheater by chance is not bussing.', 'Bussing is dishonest boosting, not an ordinary skilled player carrying a teammate. Use the report option when there is evidence that someone knowingly and repeatedly queued with a cheater.', 'A player repeatedly parties with an aimbot user to climb Competitive is bussing.', '["Boosting","Cheating","Colluding","Ranked"]'::jsonb, 'Gfinity Esports - Marvel Rivals Bussing', 'https://www.gfinityesports.com/article/marvel-rivals-what-does-bussing-mean', '{"id":"bussing","term":"Bussing","category":"Competitive Gaming","definition":"Intentionally teaming up with a cheater so the cheater can carry you to wins and artificially raise your rank. Simply being matched with a cheater by chance is not bussing.","coachNote":"Bussing is dishonest boosting, not an ordinary skilled player carrying a teammate. Use the report option when there is evidence that someone knowingly and repeatedly queued with a cheater.","example":"A player repeatedly parties with an aimbot user to climb Competitive is bussing.","relatedTerms":["Boosting","Cheating","Colluding","Ranked"],"sourceName":"Gfinity Esports - Marvel Rivals Bussing","sourceUrl":"https://www.gfinityesports.com/article/marvel-rivals-what-does-bussing-mean"}'::jsonb, '2026-07-28 06:52:40+00'::timestamptz),
  ('c9', 'C9', 'Objective', 'Accidentally leaving an objective during a capture, stall, or overtime moment and losing progress or the point because nobody is contesting it.', 'Before chasing kills, check whether someone is still touching objective. Many lost fights are really lost objective discipline.', 'The team got three eliminations but C9''d because nobody stayed on point.', '["Objective","Overtime","Point Control","Throwing"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"c9","term":"C9","category":"Objective","definition":"Accidentally leaving an objective during a capture, stall, or overtime moment and losing progress or the point because nobody is contesting it.","coachNote":"Before chasing kills, check whether someone is still touching objective. Many lost fights are really lost objective discipline.","example":"The team got three eliminations but C9''d because nobody stayed on point.","relatedTerms":["Objective","Overtime","Point Control","Throwing"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('cas', 'cas', 'Gaming Chat', 'Usually short for casual or casuals, depending on context. In game chat it can mean casual matches, casual players, or non-ranked play.', 'Usually casual or casuals.', 'play cas first', '["Chat","Mode","Casual"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"cas","term":"cas","category":"Gaming Chat","definition":"Usually short for casual or casuals, depending on context. In game chat it can mean casual matches, casual players, or non-ranked play.","coachNote":"Usually casual or casuals.","example":"play cas first","relatedTerms":["Chat","Mode","Casual"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('cc', 'cc', 'Competitive Gaming', 'Crowd control. Effects that limit enemy movement or actions, such as stuns, slows, or knockbacks.', 'Crowd control.', 'save cc for their ult', '["Ability","Control"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"cc","term":"cc","category":"Competitive Gaming","definition":"Crowd control. Effects that limit enemy movement or actions, such as stuns, slows, or knockbacks.","coachNote":"Crowd control.","example":"save cc for their ult","relatedTerms":["Ability","Control"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('cd', 'cd', 'Competitive Gaming', 'Cooldown. The time before an ability or item can be used again.', 'Cooldown.', 'heal is on cd', '["Ability","Timing"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"cd","term":"cd","category":"Competitive Gaming","definition":"Cooldown. The time before an ability or item can be used again.","coachNote":"Cooldown.","example":"heal is on cd","relatedTerms":["Ability","Timing"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('checkpoint', 'Checkpoint', 'Objective', 'A progress marker in objective modes that attackers try to capture or escort toward, often extending the round or changing the map phase.', 'Play differently around checkpoints. Attackers should save enough resources to finish the last meters; defenders should stage a real retake before progress locks in.', 'Convergence starts with a checkpoint before shifting into an escort phase.', '["Convergence","Convoy","Objective","Payload"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"checkpoint","term":"Checkpoint","category":"Objective","definition":"A progress marker in objective modes that attackers try to capture or escort toward, often extending the round or changing the map phase.","coachNote":"Play differently around checkpoints. Attackers should save enough resources to finish the last meters; defenders should stage a real retake before progress locks in.","example":"Convergence starts with a checkpoint before shifting into an escort phase.","relatedTerms":["Convergence","Convoy","Objective","Payload"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('choke-point', 'Choke Point', 'Map Control', 'A narrow map area where defenders can concentrate damage and abilities into limited space.', 'Do not trickle through a choke. Rotate, use cover, force cooldowns, or push together with defensive resources.', 'A doorway into an objective room can become a choke if the defending team controls every exit angle.', '["Brawl","Poke","Crowd Control"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"choke-point","term":"Choke Point","category":"Map Control","definition":"A narrow map area where defenders can concentrate damage and abilities into limited space.","coachNote":"Do not trickle through a choke. Rotate, use cover, force cooldowns, or push together with defensive resources.","example":"A doorway into an objective room can become a choke if the defending team controls every exit angle.","relatedTerms":["Brawl","Poke","Crowd Control"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('chrono-shield', 'Chrono Shield', 'Ranked', 'A ranked protection mechanic that can prevent a demotion or point loss after enough losses have charged it.', 'Chrono Shield is a buffer, not a strategy. If it triggers, use the saved rank as a cue to review what is causing the losing streak.', 'A fully charged Chrono Shield can shatter instead of letting a ranked loss demote you.', '["Ranked","Competitive","Demotion","Ladder"]'::jsonb, 'TechRadar - Marvel Rivals ranks and Competitive Mode', 'https://www.techradar.com/gaming/marvel-rivals-ranks', '{"id":"chrono-shield","term":"Chrono Shield","category":"Ranked","definition":"A ranked protection mechanic that can prevent a demotion or point loss after enough losses have charged it.","coachNote":"Chrono Shield is a buffer, not a strategy. If it triggers, use the saved rank as a cue to review what is causing the losing streak.","example":"A fully charged Chrono Shield can shatter instead of letting a ranked loss demote you.","relatedTerms":["Ranked","Competitive","Demotion","Ladder"],"sourceName":"TechRadar - Marvel Rivals ranks and Competitive Mode","sourceUrl":"https://www.techradar.com/gaming/marvel-rivals-ranks"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('colluding', 'Colluding', 'Competitive Gaming', 'Secretly cooperating with players on the opposing team to manipulate the match, usually by arranging for one side to lose or giving the opponents an unfair advantage.', 'Colluding requires coordination across opposing teams. A teammate playing badly or throwing on their own is not enough evidence of collusion.', 'A player deliberately feeds friends on the enemy team and gives them objectives as part of a planned win trade.', '["Win Trading","Throwing","Bussing","Cheating"]'::jsonb, 'Marvel Rivals Championship Rules', 'https://www.marvelrivals.com/MarvelRivalsChampionshipS1Global.pdf', '{"id":"colluding","term":"Colluding","category":"Competitive Gaming","definition":"Secretly cooperating with players on the opposing team to manipulate the match, usually by arranging for one side to lose or giving the opponents an unfair advantage.","coachNote":"Colluding requires coordination across opposing teams. A teammate playing badly or throwing on their own is not enough evidence of collusion.","example":"A player deliberately feeds friends on the enemy team and gives them objectives as part of a planned win trade.","relatedTerms":["Win Trading","Throwing","Bussing","Cheating"],"sourceName":"Marvel Rivals Championship Rules","sourceUrl":"https://www.marvelrivals.com/MarvelRivalsChampionshipS1Global.pdf"}'::jsonb, '2026-07-28 06:52:40+00'::timestamptz),
  ('competitive', 'Competitive', 'Game Mode', 'The ranked Marvel Rivals queue where players earn or lose rank points, climb divisions, and play higher-stakes versions of the core objective modes.', 'Competitive rewards consistency more than hero hopping. Pick a small pool, review repeated mistakes, and manage tilt between matches.', 'Competitive unlocks ranked progression and uses modes such as Domination, Convoy, and Convergence.', '["Ranked","Elo","Hero Ban","Placement Match"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"competitive","term":"Competitive","category":"Game Mode","definition":"The ranked Marvel Rivals queue where players earn or lose rank points, climb divisions, and play higher-stakes versions of the core objective modes.","coachNote":"Competitive rewards consistency more than hero hopping. Pick a small pool, review repeated mistakes, and manage tilt between matches.","example":"Competitive unlocks ranked progression and uses modes such as Domination, Convoy, and Convergence.","relatedTerms":["Ranked","Elo","Hero Ban","Placement Match"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz)
insert into public.glossary_terms (id, term, category, definition, coach_note, example, related_terms, source_name, source_url, raw_json, updated_at) values
  ('conquest', 'Conquest', 'Game Mode', 'An arcade mode where eliminations drop points that enemies can collect, while allies can pick them up to deny the score.', 'In Conquest, confirming the point drop matters as much as getting the elimination. Do not leave free points on the floor after a pick.', 'After eliminating an enemy in Conquest, step forward only if it is safe enough to collect or deny the dropped point.', '["Arcade","Final Hit","Deny","Elimination"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"conquest","term":"Conquest","category":"Game Mode","definition":"An arcade mode where eliminations drop points that enemies can collect, while allies can pick them up to deny the score.","coachNote":"In Conquest, confirming the point drop matters as much as getting the elimination. Do not leave free points on the floor after a pick.","example":"After eliminating an enemy in Conquest, step forward only if it is safe enough to collect or deny the dropped point.","relatedTerms":["Arcade","Final Hit","Deny","Elimination"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('contest', 'Contest', 'Objective', 'Standing in or near an objective area to prevent the enemy from freely capturing, scoring, or moving the objective.', 'Contest with a plan. A clean touch that buys time is useful; walking in alone with no escape usually just feeds ultimate charge.', 'A mobile hero can contest the point briefly while the team rotates back.', '["Objective","Overtime","C9","Stall"]'::jsonb, 'Coach definition informed by Marvel Rivals objective modes', 'https://marvelrivals.fandom.com/wiki/Game_Modes', '{"id":"contest","term":"Contest","category":"Objective","definition":"Standing in or near an objective area to prevent the enemy from freely capturing, scoring, or moving the objective.","coachNote":"Contest with a plan. A clean touch that buys time is useful; walking in alone with no escape usually just feeds ultimate charge.","example":"A mobile hero can contest the point briefly while the team rotates back.","relatedTerms":["Objective","Overtime","C9","Stall"],"sourceName":"Coach definition informed by Marvel Rivals objective modes","sourceUrl":"https://marvelrivals.fandom.com/wiki/Game_Modes"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('convergence', 'Convergence', 'Game Mode', 'A hybrid objective mode where attackers first capture a checkpoint, then escort a moving objective through later checkpoints if the first capture succeeds.', 'Convergence asks for two plans: how to break the first point, then how to manage the escort phase once the map opens up.', 'After winning the first checkpoint in Convergence, the attacking team swaps from point pressure into escort path control.', '["Objective","Checkpoint","Convoy","Map Control"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"convergence","term":"Convergence","category":"Game Mode","definition":"A hybrid objective mode where attackers first capture a checkpoint, then escort a moving objective through later checkpoints if the first capture succeeds.","coachNote":"Convergence asks for two plans: how to break the first point, then how to manage the escort phase once the map opens up.","example":"After winning the first checkpoint in Convergence, the attacking team swaps from point pressure into escort path control.","relatedTerms":["Objective","Checkpoint","Convoy","Map Control"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('convoy', 'Convoy', 'Game Mode', 'An objective mode where the attacking team escorts a moving objective through the map while defenders try to stop or reverse its progress.', 'Convoy is about progress management. Attackers need clean pushes around checkpoints; defenders need staged contests and retakes instead of late trickles.', 'On Convoy, attackers should group before pushing the vehicle through a dangerous choke.', '["Objective","Payload","Checkpoint","Overtime"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"convoy","term":"Convoy","category":"Game Mode","definition":"An objective mode where the attacking team escorts a moving objective through the map while defenders try to stop or reverse its progress.","coachNote":"Convoy is about progress management. Attackers need clean pushes around checkpoints; defenders need staged contests and retakes instead of late trickles.","example":"On Convoy, attackers should group before pushing the vehicle through a dangerous choke.","relatedTerms":["Objective","Payload","Checkpoint","Overtime"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('cooldown-trade', 'Cooldown Trade', 'Combat', 'An exchange where one team''s position or pressure forces enemy abilities, creating a window to punish with your own cooldowns afterward.', 'Power positions are strong because they can make enemies spend resources first. Survive the response, then punish while their tools are missing.', 'A Strategist angle forces enemy mobility and a defensive cooldown, then your Vanguard engages while those tools are down.', '["Power Position","Passive Pressure","Sustain","Engage"]'::jsonb, 'Power Positions guide notes', '/power-positions', '{"id":"cooldown-trade","term":"Cooldown Trade","category":"Combat","definition":"An exchange where one team''s position or pressure forces enemy abilities, creating a window to punish with your own cooldowns afterward.","coachNote":"Power positions are strong because they can make enemies spend resources first. Survive the response, then punish while their tools are missing.","example":"A Strategist angle forces enemy mobility and a defensive cooldown, then your Vanguard engages while those tools are down.","relatedTerms":["Power Position","Passive Pressure","Sustain","Engage"],"sourceName":"Power Positions guide notes","sourceUrl":"/power-positions"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('cover', 'Cover', 'Positioning', 'Map geometry or objects that block line of sight, reduce visible hitbox, and create a safe reset point during pressure trades.', 'Cover is your default state, not a panic button. Peek with a purpose, then return before the enemy gets repeated shots.', 'A wall, payload corner, high-ground ledge, doorway, or box can all function as cover depending on the angle.', '["Hitbox Minimization","One-Angle Rule","Parallel Peek","Sightline"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"cover","term":"Cover","category":"Positioning","definition":"Map geometry or objects that block line of sight, reduce visible hitbox, and create a safe reset point during pressure trades.","coachNote":"Cover is your default state, not a panic button. Peek with a purpose, then return before the enemy gets repeated shots.","example":"A wall, payload corner, high-ground ledge, doorway, or box can all function as cover depending on the angle.","relatedTerms":["Hitbox Minimization","One-Angle Rule","Parallel Peek","Sightline"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('crowd-control', 'Crowd Control', 'Combat', 'Abilities that limit enemy movement, interrupt actions, prevent ability use, or otherwise disrupt control of a hero.', 'Track crowd-control cooldowns before diving or using an ultimate that can be interrupted.', 'Stuns, immobilizes, knock downs, and charms are common crowd-control effects.', '["Dive","Peeling","Choke Point"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"crowd-control","term":"Crowd Control","category":"Combat","definition":"Abilities that limit enemy movement, interrupt actions, prevent ability use, or otherwise disrupt control of a hero.","coachNote":"Track crowd-control cooldowns before diving or using an ultimate that can be interrupted.","example":"Stuns, immobilizes, knock downs, and charms are common crowd-control effects.","relatedTerms":["Dive","Peeling","Choke Point"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('custom-game', 'Custom Game', 'Game Mode', 'A private or custom rules match setup where players can choose modes, maps, and settings outside normal matchmaking.', 'Custom games are excellent for map walkthroughs, team drills, and testing hero interactions without match pressure.', 'A team can load a Custom Game to practice a first-point Convergence setup.', '["Practice","Map Control","Team Composition","Objective"]'::jsonb, 'Marvel Rivals Wiki - Game Modes', 'https://marvelrivals.fandom.com/wiki/Game_Modes', '{"id":"custom-game","term":"Custom Game","category":"Game Mode","definition":"A private or custom rules match setup where players can choose modes, maps, and settings outside normal matchmaking.","coachNote":"Custom games are excellent for map walkthroughs, team drills, and testing hero interactions without match pressure.","example":"A team can load a Custom Game to practice a first-point Convergence setup.","relatedTerms":["Practice","Map Control","Team Composition","Objective"],"sourceName":"Marvel Rivals Wiki - Game Modes","sourceUrl":"https://marvelrivals.fandom.com/wiki/Game_Modes"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('damage-boost', 'Damage Boost', 'Status Effect', 'A buff that increases the amount of damage a hero deals while the effect is active.', 'Damage boost is strongest when paired with timing. Boost a planned burst window, not random poke that the enemy can safely heal.', 'A Strategist damage boost can help a Duelist finish an exposed target faster.', '["Buff","Damage Build","Target Priority","Cooldown Trade"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"damage-boost","term":"Damage Boost","category":"Status Effect","definition":"A buff that increases the amount of damage a hero deals while the effect is active.","coachNote":"Damage boost is strongest when paired with timing. Boost a planned burst window, not random poke that the enemy can safely heal.","example":"A Strategist damage boost can help a Duelist finish an exposed target faster.","relatedTerms":["Buff","Damage Build","Target Priority","Cooldown Trade"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('damage-build', 'Damage Build', 'Build Theory', 'A build plan centered on maximizing damage uptime, burst windows, target pressure, and finishing power.', 'Damage builds still need setup. The mistake is treating damage as constant spam instead of pairing it with angles, forced cooldowns, and target priority.', 'A Hela damage build plays for clean sightlines, off-angles, and burst timing after enemy defensive tools are spent.', '["Hero Build","Target Priority","Off-Angle","Poke","Cooldown Trade"]'::jsonb, 'Coach definition for Marvel Rivals build planning', '/glossary', '{"id":"damage-build","term":"Damage Build","category":"Build Theory","definition":"A build plan centered on maximizing damage uptime, burst windows, target pressure, and finishing power.","coachNote":"Damage builds still need setup. The mistake is treating damage as constant spam instead of pairing it with angles, forced cooldowns, and target priority.","example":"A Hela damage build plays for clean sightlines, off-angles, and burst timing after enemy defensive tools are spent.","relatedTerms":["Hero Build","Target Priority","Off-Angle","Poke","Cooldown Trade"],"sourceName":"Coach definition for Marvel Rivals build planning","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('damage-reduction', 'Damage Reduction', 'Status Effect', 'A buff that reduces incoming damage while active, helping a hero survive pressure or commit into danger.', 'Damage reduction is a timing tool. Use it to cross space, survive enemy burst, or hold a position long enough for help to arrive.', 'A Vanguard may use damage reduction before leading the team through a choke.', '["Buff","Sustain","Vanguard","Engage"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"damage-reduction","term":"Damage Reduction","category":"Status Effect","definition":"A buff that reduces incoming damage while active, helping a hero survive pressure or commit into danger.","coachNote":"Damage reduction is a timing tool. Use it to cross space, survive enemy burst, or hold a position long enough for help to arrive.","example":"A Vanguard may use damage reduction before leading the team through a choke.","relatedTerms":["Buff","Sustain","Vanguard","Engage"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('dc', 'DC', 'Gaming Chat', 'Short for disconnected. A player has lost connection to the match or left unexpectedly.', 'If a teammate DCs, play for delay and survivability until the match system or teammate reconnect decides what happens next.', 'Our Vanguard DC''d before the second fight.', '["Chat","Matchmaking","Competitive","AFK"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"dc","term":"DC","category":"Gaming Chat","definition":"Short for disconnected. A player has lost connection to the match or left unexpectedly.","coachNote":"If a teammate DCs, play for delay and survivability until the match system or teammate reconnect decides what happens next.","example":"Our Vanguard DC''d before the second fight.","relatedTerms":["Chat","Matchmaking","Competitive","AFK"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('destructible-environment', 'Destructible Environment', 'Map Control', 'Map geometry that can be damaged or broken, changing sightlines, cover, routes, and fight positions during a match.', 'Use destruction deliberately. Breaking cover can expose enemies, but it can also remove your own reset point if you are careless.', 'Destroying a wall can open a new sightline onto an objective or deny an enemy''s safe corner.', '["Cover","Sightline","Map Control","Power Position"]'::jsonb, 'Marvel Rivals gameplay overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"destructible-environment","term":"Destructible Environment","category":"Map Control","definition":"Map geometry that can be damaged or broken, changing sightlines, cover, routes, and fight positions during a match.","coachNote":"Use destruction deliberately. Breaking cover can expose enemies, but it can also remove your own reset point if you are careless.","example":"Destroying a wall can open a new sightline onto an objective or deny an enemy''s safe corner.","relatedTerms":["Cover","Sightline","Map Control","Power Position"],"sourceName":"Marvel Rivals gameplay overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('diff', 'diff', 'Competitive Gaming', 'Short for difference. Often used to say one player or role outperformed the other side.', 'A performance gap between players or roles.', 'tank diff', '["Competitive","Chat"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"diff","term":"diff","category":"Competitive Gaming","definition":"Short for difference. Often used to say one player or role outperformed the other side.","coachNote":"A performance gap between players or roles.","example":"tank diff","relatedTerms":["Competitive","Chat"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('dive', 'Dive', 'Positioning', 'A high-mobility attack where heroes collapse onto a single target, often a Strategist, then escape or reset before the enemy team can punish.', 'Call the target before diving. One hero jumping alone is usually feeding; two or three jumping together is pressure.', 'Spider-Man, Black Panther, Magik, and Daredevil are examples of dive-friendly heroes.', '["Flanking","Peeling","Backline"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"dive","term":"Dive","category":"Positioning","definition":"A high-mobility attack where heroes collapse onto a single target, often a Strategist, then escape or reset before the enemy team can punish.","coachNote":"Call the target before diving. One hero jumping alone is usually feeding; two or three jumping together is pressure.","example":"Spider-Man, Black Panther, Magik, and Daredevil are examples of dive-friendly heroes.","relatedTerms":["Flanking","Peeling","Backline"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('domination', 'Domination', 'Game Mode', 'A control-point mode where both teams fight over a single objective zone and win the round by holding it to the required score.', 'Domination rewards clean rotations and retakes. Do not spend ultimates after the point is already lost unless the team can actually flip it.', 'A team may win Domination by capturing two objective rounds before the other team does.', '["Objective","Point Control","Retake","Team Fight"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"domination","term":"Domination","category":"Game Mode","definition":"A control-point mode where both teams fight over a single objective zone and win the round by holding it to the required score.","coachNote":"Domination rewards clean rotations and retakes. Do not spend ultimates after the point is already lost unless the team can actually flip it.","example":"A team may win Domination by capturing two objective rounds before the other team does.","relatedTerms":["Objective","Point Control","Retake","Team Fight"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('doom-match', 'Doom Match', 'Game Mode', 'A free-for-all arcade mode where players compete for Final Hits, with winners determined by the top half of the lobby or the target score.', 'Doom Match is about finishing power and survival. Chasing every duel can hand Final Hits to third parties.', 'In Doom Match, a low-health escape can be better than forcing a duel that another player can clean up.', '["Arcade","Final Hit","Free For All","Elimination"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"doom-match","term":"Doom Match","category":"Game Mode","definition":"A free-for-all arcade mode where players compete for Final Hits, with winners determined by the top half of the lobby or the target score.","coachNote":"Doom Match is about finishing power and survival. Chasing every duel can hand Final Hits to third parties.","example":"In Doom Match, a low-health escape can be better than forcing a duel that another player can clean up.","relatedTerms":["Arcade","Final Hit","Free For All","Elimination"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('dope', 'dope', 'Internet Slang', 'Slang for something good, cool, impressive, or desirable. In gaming chat it may describe rewards, cosmetics, plays, or gear.', 'Cool, good, impressive, or desirable.', 'that skin is dope', '["Chat","Compliment","Slang"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"dope","term":"dope","category":"Internet Slang","definition":"Slang for something good, cool, impressive, or desirable. In gaming chat it may describe rewards, cosmetics, plays, or gear.","coachNote":"Cool, good, impressive, or desirable.","example":"that skin is dope","relatedTerms":["Chat","Compliment","Slang"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('dps', 'DPS', 'Role', 'Damage per second; commonly used by players as another word for Duelist.', 'DPS picks still need a job: poke, dive, flank, brawl, anti-air, or objective pressure.', 'Hela, Spider-Man, and The Punisher are Duelists.', '["Duelist","Poke","Dive"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"dps","term":"DPS","category":"Role","definition":"Damage per second; commonly used by players as another word for Duelist.","coachNote":"DPS picks still need a job: poke, dive, flank, brawl, anti-air, or objective pressure.","example":"Hela, Spider-Man, and The Punisher are Duelists.","relatedTerms":["Duelist","Poke","Dive"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('duelist', 'Duelist', 'Role', 'The Marvel Rivals damage role. Duelists focus on pressure, burst, finishing kills, flanking, or controlling sightlines through damage threat.', 'Duelist does not mean ignore the team. Pick a damage job: break shields, pressure flyers, finish isolated targets, or open an angle for the next engage.', 'Hela, Spider-Man, and The Punisher are Duelists.', '["DPS","Damage Build","Flanking","Target Priority"]'::jsonb, 'Marvel Rivals gameplay overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"duelist","term":"Duelist","category":"Role","definition":"The Marvel Rivals damage role. Duelists focus on pressure, burst, finishing kills, flanking, or controlling sightlines through damage threat.","coachNote":"Duelist does not mean ignore the team. Pick a damage job: break shields, pressure flyers, finish isolated targets, or open an angle for the next engage.","example":"Hela, Spider-Man, and The Punisher are Duelists.","relatedTerms":["DPS","Damage Build","Flanking","Target Priority"],"sourceName":"Marvel Rivals gameplay overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('earthbound', 'Earthbound', 'Status Effect', 'A debuff that disables movement abilities such as dashes or jumps, making mobile heroes easier to punish.', 'Earthbound creates a focus-fire window. Call the target immediately because mobility heroes become much easier to finish while grounded.', 'Applying Earthbound to a flyer can stop their escape long enough for the team to punish.', '["Debuff","Crowd Control","Mobility Build","Flyer"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"earthbound","term":"Earthbound","category":"Status Effect","definition":"A debuff that disables movement abilities such as dashes or jumps, making mobile heroes easier to punish.","coachNote":"Earthbound creates a focus-fire window. Call the target immediately because mobility heroes become much easier to finish while grounded.","example":"Applying Earthbound to a flyer can stop their escape long enough for the team to punish.","relatedTerms":["Debuff","Crowd Control","Mobility Build","Flyer"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('elo', 'Elo', 'Ranked', 'A player rating concept used as shorthand for ranked skill or matchmaking strength. In Marvel Rivals discussion, players use it to describe rank movement and match quality.', 'Do not judge improvement only by Elo after one session. Look for repeated decisions that make your next ten games more stable.', 'A player might say they are in low Elo when their ranked matches feel less coordinated.', '["Ranked","Competitive","Ladder","Matchmaking"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"elo","term":"Elo","category":"Ranked","definition":"A player rating concept used as shorthand for ranked skill or matchmaking strength. In Marvel Rivals discussion, players use it to describe rank movement and match quality.","coachNote":"Do not judge improvement only by Elo after one session. Look for repeated decisions that make your next ten games more stable.","example":"A player might say they are in low Elo when their ranked matches feel less coordinated.","relatedTerms":["Ranked","Competitive","Ladder","Matchmaking"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('enemy-hitbox-maximization', 'Enemy Hitbox Maximization', 'Positioning', 'Adjusting your angle so the enemy is more exposed from your perspective while you still keep your own cover.', 'Small left-right position changes can turn a nearly hidden enemy into a hittable target without making you wide open.', 'Shifting slightly left around a corner so you can see more of an enemy trying to hide behind cover.', '["Cover","Off-Angle","Sightline"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"enemy-hitbox-maximization","term":"Enemy Hitbox Maximization","category":"Positioning","definition":"Adjusting your angle so the enemy is more exposed from your perspective while you still keep your own cover.","coachNote":"Small left-right position changes can turn a nearly hidden enemy into a hittable target without making you wide open.","example":"Shifting slightly left around a corner so you can see more of an enemy trying to hide behind cover.","relatedTerms":["Cover","Off-Angle","Sightline"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('engage', 'Engage', 'Combat', 'The moment a team or player commits into a fight with pressure, mobility, cooldowns, or an ultimate.', 'A good engage has a target, a timing trigger, and an exit or follow-up plan. Going in alone is usually not an engage; it is a feed.', 'Thor jumping the backline as his Duelists open side angles is an engage.', '["Dive","Timing","Target Priority","Cooldown Trade"]'::jsonb, 'Power Positions guide notes', '/power-positions', '{"id":"engage","term":"Engage","category":"Combat","definition":"The moment a team or player commits into a fight with pressure, mobility, cooldowns, or an ultimate.","coachNote":"A good engage has a target, a timing trigger, and an exit or follow-up plan. Going in alone is usually not an engage; it is a feed.","example":"Thor jumping the backline as his Duelists open side angles is an engage.","relatedTerms":["Dive","Timing","Target Priority","Cooldown Trade"],"sourceName":"Power Positions guide notes","sourceUrl":"/power-positions"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('feed', 'feed', 'Competitive Gaming', 'To die repeatedly or give the enemy easy value, especially when those deaths charge enemy ultimates or create unfair fights.', 'Feeding is often a positioning or timing problem, not just a mechanics problem. Reset, group, and stop entering fights before the team is ready.', 'Do not feed before our supports get back from spawn.', '["Competitive","Behavior","Inting","Throwing","Ult"]'::jsonb, 'Manual glossary entry', '/glossary', '{"id":"feed","term":"feed","category":"Competitive Gaming","definition":"To die repeatedly or give the enemy easy value, especially when those deaths charge enemy ultimates or create unfair fights.","coachNote":"Feeding is often a positioning or timing problem, not just a mechanics problem. Reset, group, and stop entering fights before the team is ready.","example":"Do not feed before our supports get back from spawn.","relatedTerms":["Competitive","Behavior","Inting","Throwing","Ult"],"sourceName":"Manual glossary entry","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz)
insert into public.glossary_terms (id, term, category, definition, coach_note, example, related_terms, source_name, source_url, raw_json, updated_at) values
  ('final-hit', 'Final Hit', 'Combat', 'The finishing blow that secures an elimination credit, especially important in modes that score or rank players by final hits.', 'Final Hits matter, but do not tunnel on them. Pressuring the right target can win a fight even if someone else gets the final blow.', 'Doom Match rewards players for securing Final Hits before the match ends.', '["Elimination","Doom Match","Target Priority","Damage Build"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"final-hit","term":"Final Hit","category":"Combat","definition":"The finishing blow that secures an elimination credit, especially important in modes that score or rank players by final hits.","coachNote":"Final Hits matter, but do not tunnel on them. Pressuring the right target can win a fight even if someone else gets the final blow.","example":"Doom Match rewards players for securing Final Hits before the match ends.","relatedTerms":["Elimination","Doom Match","Target Priority","Damage Build"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('flanking', 'Flanking', 'Positioning', 'Attacking from the side or behind, usually bypassing the Vanguard line to pressure Strategists or long-range damage heroes.', 'A flank is strongest when your frontline is already pulling attention. If nobody is looking at your team, they will all look at you.', 'A Duelist wrapping behind the fight to threaten supports is flanking.', '["Dive","Backline","Off-Angle"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"flanking","term":"Flanking","category":"Positioning","definition":"Attacking from the side or behind, usually bypassing the Vanguard line to pressure Strategists or long-range damage heroes.","coachNote":"A flank is strongest when your frontline is already pulling attention. If nobody is looking at your team, they will all look at you.","example":"A Duelist wrapping behind the fight to threaten supports is flanking.","relatedTerms":["Dive","Backline","Off-Angle"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('flexible-healer', 'Flexible Healer', 'Role', 'A healer who can shift between primary sustain, burst recovery, utility, and offensive contribution as the team composition or fight changes.', 'Flexibility requires a clear priority. Identify whether the current fight needs more healing, utility, survival, or pressure instead of trying to do everything at once.', 'The flexible healer handles routine sustain, then switches to utility when the team starts its engage.', '["Primary Healer","Off-Healer","Burst Healer","Utility Build"]'::jsonb, 'PC Gamer Marvel Rivals team-composition analysis', 'https://www.pcgamer.com/games/third-person-shooter/marvel-rivals-tier-list-best-characters/', '{"id":"flexible-healer","term":"Flexible Healer","category":"Role","definition":"A healer who can shift between primary sustain, burst recovery, utility, and offensive contribution as the team composition or fight changes.","coachNote":"Flexibility requires a clear priority. Identify whether the current fight needs more healing, utility, survival, or pressure instead of trying to do everything at once.","example":"The flexible healer handles routine sustain, then switches to utility when the team starts its engage.","relatedTerms":["Primary Healer","Off-Healer","Burst Healer","Utility Build"],"sourceName":"PC Gamer Marvel Rivals team-composition analysis","sourceUrl":"https://www.pcgamer.com/games/third-person-shooter/marvel-rivals-tier-list-best-characters/"}'::jsonb, '2026-07-27 08:06:06+00'::timestamptz),
  ('flyer', 'Flyer', 'Positioning', 'A hero who can stay airborne for extended periods or indefinitely, changing how teams must control vertical space.', 'Against flyers, assign hitscan pressure or force objectives where vertical angles are less valuable.', 'Iron Man, Storm, Ultron, and Angela are examples of heroes with sustained flight.', '["Hitscan","Poke","High Ground"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"flyer","term":"Flyer","category":"Positioning","definition":"A hero who can stay airborne for extended periods or indefinitely, changing how teams must control vertical space.","coachNote":"Against flyers, assign hitscan pressure or force objectives where vertical angles are less valuable.","example":"Iron Man, Storm, Ultron, and Angela are examples of heroes with sustained flight.","relatedTerms":["Hitscan","Poke","High Ground"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('free-fight', 'Free Fight', 'Game Mode', 'An Arcade-style mode using Quick Match-style rules while allowing duplicate heroes, with ban rules used to keep compositions from becoming too warped.', 'Free Fight changes composition expectations. Do not assume normal role balance or duplicate-hero limits apply.', 'A Free Fight lobby can include repeated hero picks that standard queues would restrict.', '["Arcade","Quick Match","Hero Ban","Team Composition"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"free-fight","term":"Free Fight","category":"Game Mode","definition":"An Arcade-style mode using Quick Match-style rules while allowing duplicate heroes, with ban rules used to keep compositions from becoming too warped.","coachNote":"Free Fight changes composition expectations. Do not assume normal role balance or duplicate-hero limits apply.","example":"A Free Fight lobby can include repeated hero picks that standard queues would restrict.","relatedTerms":["Arcade","Quick Match","Hero Ban","Team Composition"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('frontline', 'Frontline', 'Coach Term', 'The forward pressure line where Vanguards and close-range heroes contest space, block routes, and start engagements.', 'Frontline is about space, not just standing first. Good frontline play creates safe angles for the rest of the team.', 'A Groot walling a doorway while allies rotate is controlling the frontline.', '["Tank","Brawl","Choke Point"]'::jsonb, 'Coach definition informed by Marvel Rivals role terminology', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"frontline","term":"Frontline","category":"Coach Term","definition":"The forward pressure line where Vanguards and close-range heroes contest space, block routes, and start engagements.","coachNote":"Frontline is about space, not just standing first. Good frontline play creates safe angles for the rest of the team.","example":"A Groot walling a doorway while allies rotate is controlling the frontline.","relatedTerms":["Tank","Brawl","Choke Point"],"sourceName":"Coach definition informed by Marvel Rivals role terminology","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('gank', 'gank', 'Competitive Gaming', 'To ambush an enemy, usually with help from another player or from an unexpected angle.', 'An ambush on an enemy player.', 'watch for the gank', '["Strategy","Combat"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"gank","term":"gank","category":"Competitive Gaming","definition":"To ambush an enemy, usually with help from another player or from an unexpected angle.","coachNote":"An ambush on an enemy player.","example":"watch for the gank","relatedTerms":["Strategy","Combat"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('gas-lighting', 'gas-lighting', 'Internet Slang', 'Manipulating someone into doubting what they saw, remembered, or understood. In game chat, it is often used when someone denies obvious mistakes or tries to rewrite what happened.', 'Use this term carefully. Not every disagreement or bad call is gas-lighting; look for repeated denial or blame-shifting that makes teammates question reality.', 'Saying the team never grouped after everyone clearly waited together can feel like gas-lighting.', '["Chat","Behavior","Blame","Toxicity"]'::jsonb, 'Manual glossary entry', '/glossary', '{"id":"gas-lighting","term":"gas-lighting","category":"Internet Slang","definition":"Manipulating someone into doubting what they saw, remembered, or understood. In game chat, it is often used when someone denies obvious mistakes or tries to rewrite what happened.","coachNote":"Use this term carefully. Not every disagreement or bad call is gas-lighting; look for repeated denial or blame-shifting that makes teammates question reality.","example":"Saying the team never grouped after everyone clearly waited together can feel like gas-lighting.","relatedTerms":["Chat","Behavior","Blame","Toxicity"],"sourceName":"Manual glossary entry","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('gg', 'gg', 'Gaming Chat', 'Good game. Usually said after a match ends.', 'Good game.', 'gg team', '["Chat","Match End"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"gg","term":"gg","category":"Gaming Chat","definition":"Good game. Usually said after a match ends.","coachNote":"Good game.","example":"gg team","relatedTerms":["Chat","Match End"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('glhf', 'glhf', 'Gaming Chat', 'Good luck, have fun. A friendly phrase used at the start of a match.', 'Good luck, have fun.', 'glhf everyone', '["Sportsmanship","Chat","Match Start"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"glhf","term":"glhf","category":"Gaming Chat","definition":"Good luck, have fun. A friendly phrase used at the start of a match.","coachNote":"Good luck, have fun.","example":"glhf everyone","relatedTerms":["Sportsmanship","Chat","Match Start"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('glnm', 'glnm', 'Gaming Chat', 'Good luck next match. A friendly phrase used after a game to wish someone better luck in their next queue.', 'Good luck next match.', 'glnm, you got this', '["Sportsmanship","Chat","Match End","gg"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"glnm","term":"glnm","category":"Gaming Chat","definition":"Good luck next match. A friendly phrase used after a game to wish someone better luck in their next queue.","coachNote":"Good luck next match.","example":"glnm, you got this","relatedTerms":["Sportsmanship","Chat","Match End","gg"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-09 07:33:05+00'::timestamptz),
  ('healer', 'Healer', 'Role', 'In Marvel Rivals the healers are the Strategists. The game names the role Strategist rather than Healer or Support, but any hero whose role is Strategist is a healer.', '"How many healers do we have" means "how many Strategists", and the answer you usually want is two.', 'Luna Snow is a Strategist, so yes, she is a healer.', '["Strategist","Primary Healer","Off-Healer"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"healer","term":"Healer","category":"Role","definition":"In Marvel Rivals the healers are the Strategists. The game names the role Strategist rather than Healer or Support, but any hero whose role is Strategist is a healer.","coachNote":"\"How many healers do we have\" means \"how many Strategists\", and the answer you usually want is two.","example":"Luna Snow is a Strategist, so yes, she is a healer.","relatedTerms":["Strategist","Primary Healer","Off-Healer"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-10-26 23:38:59+00'::timestamptz),
  ('healing-over-time', 'Healing Over Time', 'Status Effect', 'A healing effect that restores health gradually for a duration instead of all at once.', 'Healing over time needs patience and cover. If you keep taking burst damage while it ticks, the value disappears before it stabilizes you.', 'A Strategist may apply healing over time before the team re-engages.', '["Sustain","Support","Strategist","Healing Boost"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"healing-over-time","term":"Healing Over Time","category":"Status Effect","definition":"A healing effect that restores health gradually for a duration instead of all at once.","coachNote":"Healing over time needs patience and cover. If you keep taking burst damage while it ticks, the value disappears before it stabilizes you.","example":"A Strategist may apply healing over time before the team re-engages.","relatedTerms":["Sustain","Support","Strategist","Healing Boost"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('healing-reduction', 'Healing Reduction', 'Status Effect', 'A debuff that reduces the healing a hero receives, making sustain and support resources less effective during the effect.', 'When healing reduction lands, swap from slow pressure to confirmation. The window is valuable because normal sustain cannot fully answer it.', 'A healing reduction effect can make a high-sustain Vanguard much easier to finish.', '["Debuff","Sustain","Support","Target Priority"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"healing-reduction","term":"Healing Reduction","category":"Status Effect","definition":"A debuff that reduces the healing a hero receives, making sustain and support resources less effective during the effect.","coachNote":"When healing reduction lands, swap from slow pressure to confirmation. The window is valuable because normal sustain cannot fully answer it.","example":"A healing reduction effect can make a high-sustain Vanguard much easier to finish.","relatedTerms":["Debuff","Sustain","Support","Target Priority"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('hero-ban', 'Hero Ban', 'Ranked', 'A competitive draft rule where teams remove selected heroes from the match so neither side can play them.', 'Ban heroes that break your planned composition, dominate the current map, or hard-counter your team''s best win condition.', 'A team might ban a strong flyer if its composition has weak anti-air pressure.', '["Competitive","Draft","Meta","Team Composition"]'::jsonb, 'TechRadar - Marvel Rivals ranks and Competitive Mode', 'https://www.techradar.com/gaming/marvel-rivals-ranks', '{"id":"hero-ban","term":"Hero Ban","category":"Ranked","definition":"A competitive draft rule where teams remove selected heroes from the match so neither side can play them.","coachNote":"Ban heroes that break your planned composition, dominate the current map, or hard-counter your team''s best win condition.","example":"A team might ban a strong flyer if its composition has weak anti-air pressure.","relatedTerms":["Competitive","Draft","Meta","Team Composition"],"sourceName":"TechRadar - Marvel Rivals ranks and Competitive Mode","sourceUrl":"https://www.techradar.com/gaming/marvel-rivals-ranks"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('hero-build', 'Hero Build', 'Build Theory', 'A plan for emphasizing one part of a hero''s kit through team composition, playstyle, cooldown priority, positioning, and fight timing.', 'Marvel Rivals does not use item builds like a MOBA. A build is usually a coaching plan: what ability gets protected, what cooldown starts fights, what stat matters, and what teammates make that plan stronger.', 'Building Rocket Raccoon around revive, armor packs, and lane support is different from building him around damage uptime.', '["Utility Build","Damage Build","Sustain Build","Mobility Build","Ultimate Build"]'::jsonb, 'Coach definition for Marvel Rivals build planning', '/glossary', '{"id":"hero-build","term":"Hero Build","category":"Build Theory","definition":"A plan for emphasizing one part of a hero''s kit through team composition, playstyle, cooldown priority, positioning, and fight timing.","coachNote":"Marvel Rivals does not use item builds like a MOBA. A build is usually a coaching plan: what ability gets protected, what cooldown starts fights, what stat matters, and what teammates make that plan stronger.","example":"Building Rocket Raccoon around revive, armor packs, and lane support is different from building him around damage uptime.","relatedTerms":["Utility Build","Damage Build","Sustain Build","Mobility Build","Ultimate Build"],"sourceName":"Coach definition for Marvel Rivals build planning","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('high-ground', 'High Ground', 'Coach Term', 'An elevated position that improves sightlines, cover options, and pressure over enemies below.', 'High ground is valuable until the objective or enemy rotation makes it irrelevant. Do not stay up there after the fight moves away.', 'A Punisher holding a balcony above a choke can pressure enemies before they reach point.', '["Poke","Flyer","Off-Angle"]'::jsonb, 'Coach definition informed by Marvel Rivals map-control terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"high-ground","term":"High Ground","category":"Coach Term","definition":"An elevated position that improves sightlines, cover options, and pressure over enemies below.","coachNote":"High ground is valuable until the objective or enemy rotation makes it irrelevant. Do not stay up there after the fight moves away.","example":"A Punisher holding a balcony above a choke can pressure enemies before they reach point.","relatedTerms":["Poke","Flyer","Off-Angle"],"sourceName":"Coach definition informed by Marvel Rivals map-control terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('hitbox-minimization', 'Hitbox Minimization', 'Positioning', 'Using cover and distance from a cover edge so the enemy can see and shoot as little of your character model as possible.', 'Being near cover is not enough. If your full body is visible, you are giving the enemy too many chances to hit you.', 'Backing up behind horizontal cover until only your head is visible is hitbox minimization.', '["Cover","Peeking","One-Angle Rule"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"hitbox-minimization","term":"Hitbox Minimization","category":"Positioning","definition":"Using cover and distance from a cover edge so the enemy can see and shoot as little of your character model as possible.","coachNote":"Being near cover is not enough. If your full body is visible, you are giving the enemy too many chances to hit you.","example":"Backing up behind horizontal cover until only your head is visible is hitbox minimization.","relatedTerms":["Cover","Peeking","One-Angle Rule"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('hitscan', 'Hitscan', 'Combat', 'A ranged attack that reaches its target immediately when fired instead of traveling as a projectile.', 'Hitscan pressure is valuable into flyers and fast flankers because there is no projectile travel time to lead.', 'The wiki lists examples such as Hela, Phoenix, and Ultron attacks.', '["Flyer","Poke"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"hitscan","term":"Hitscan","category":"Combat","definition":"A ranged attack that reaches its target immediately when fired instead of traveling as a projectile.","coachNote":"Hitscan pressure is valuable into flyers and fast flankers because there is no projectile travel time to lead.","example":"The wiki lists examples such as Hela, Phoenix, and Ultron attacks.","relatedTerms":["Flyer","Poke"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('immobilize', 'Immobilize', 'Status Effect', 'A debuff that prevents a hero from moving until the effect ends, sometimes described as imprisoning the target.', 'Immobilize is strongest when teammates are ready to follow up. A rooted target still needs damage or displacement to become a won fight.', 'Immobilizing a flanker can give the backline time to turn and eliminate them.', '["Crowd Control","Debuff","Peeling","Target Priority"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"immobilize","term":"Immobilize","category":"Status Effect","definition":"A debuff that prevents a hero from moving until the effect ends, sometimes described as imprisoning the target.","coachNote":"Immobilize is strongest when teammates are ready to follow up. A rooted target still needs damage or displacement to become a won fight.","example":"Immobilizing a flanker can give the backline time to turn and eliminate them.","relatedTerms":["Crowd Control","Debuff","Peeling","Target Priority"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('inflating-the-ladder', 'Inflating the Ladder', 'Ranked', 'A ranked-ladder distortion where smurfs or alternate accounts temporarily add high-skill players into lower visible ranks, making those ranks feel harder or more populated with strong players than they really are.', 'Do not read every hard lobby as proof you belong lower. Smurfs can make a rank feel uneven because the account rank and the player''s real skill do not match.', 'A Diamond-level player on a fresh Gold account can inflate Gold by playing far above the lobby''s expected skill while climbing through it.', '["Smurf","Matchmaking","Ranked","Ladder"]'::jsonb, 'Coach definition for Marvel Rivals ranked discussion', '/glossary', '{"id":"inflating-the-ladder","term":"Inflating the Ladder","category":"Ranked","definition":"A ranked-ladder distortion where smurfs or alternate accounts temporarily add high-skill players into lower visible ranks, making those ranks feel harder or more populated with strong players than they really are.","coachNote":"Do not read every hard lobby as proof you belong lower. Smurfs can make a rank feel uneven because the account rank and the player''s real skill do not match.","example":"A Diamond-level player on a fresh Gold account can inflate Gold by playing far above the lobby''s expected skill while climbing through it.","relatedTerms":["Smurf","Matchmaking","Ranked","Ladder"],"sourceName":"Coach definition for Marvel Rivals ranked discussion","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('inting', 'inting', 'Competitive Gaming', 'Intentionally feeding, or playing so recklessly that it looks intentional.', 'Playing recklessly or intentionally feeding.', 'stop inting mid', '["Competitive","Behavior"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"inting","term":"inting","category":"Competitive Gaming","definition":"Intentionally feeding, or playing so recklessly that it looks intentional.","coachNote":"Playing recklessly or intentionally feeding.","example":"stop inting mid","relatedTerms":["Competitive","Behavior"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('invulnerable', 'Invulnerable', 'Status Effect', 'A state where a hero is temporarily immune to incoming damage.', 'Do not waste burst into invulnerability. Track when the effect ends and aim to punish the exit timing instead.', 'Some abilities briefly make a hero invulnerable during movement or transformation.', '["Cooldown Trade","Damage Reduction","Phased","Ultimate"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"invulnerable","term":"Invulnerable","category":"Status Effect","definition":"A state where a hero is temporarily immune to incoming damage.","coachNote":"Do not waste burst into invulnerability. Track when the effect ends and aim to punish the exit timing instead.","example":"Some abilities briefly make a hero invulnerable during movement or transformation.","relatedTerms":["Cooldown Trade","Damage Reduction","Phased","Ultimate"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('lane-control', 'Lane Control', 'Map Control', 'The ability to influence which routes, sightlines, and side paths the enemy can safely use during a fight.', 'Think in main lane and side lanes. Strong teams do not only walk the shortest route; they open side pressure and make enemies answer multiple directions.', 'Taking a power position that sees main and a side doorway gives your team lane control without standing on point.', '["Power Position","Off-Angle","Poke","Choke Point"]'::jsonb, 'Power Positions guide notes', '/power-positions', '{"id":"lane-control","term":"Lane Control","category":"Map Control","definition":"The ability to influence which routes, sightlines, and side paths the enemy can safely use during a fight.","coachNote":"Think in main lane and side lanes. Strong teams do not only walk the shortest route; they open side pressure and make enemies answer multiple directions.","example":"Taking a power position that sees main and a side doorway gives your team lane control without standing on point.","relatedTerms":["Power Position","Off-Angle","Poke","Choke Point"],"sourceName":"Power Positions guide notes","sourceUrl":"/power-positions"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('lifesteal', 'Lifesteal', 'Status Effect', 'A healing effect that restores health based on a portion of the damage dealt to enemies.', 'Lifesteal rewards uptime, but it still loses to burst or crowd control. Keep hitting only when your position lets you survive the trade.', 'A hero with lifesteal can sustain longer while actively damaging enemies.', '["Sustain","Damage Build","Healing Reduction","Brawl"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"lifesteal","term":"Lifesteal","category":"Status Effect","definition":"A healing effect that restores health based on a portion of the damage dealt to enemies.","coachNote":"Lifesteal rewards uptime, but it still loses to burst or crowd control. Keep hitting only when your position lets you survive the trade.","example":"A hero with lifesteal can sustain longer while actively damaging enemies.","relatedTerms":["Sustain","Damage Build","Healing Reduction","Brawl"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz)
insert into public.glossary_terms (id, term, category, definition, coach_note, example, related_terms, source_name, source_url, raw_json, updated_at) values
  ('lol', 'lol', 'Internet Slang', 'Laughing out loud. Used to show something is funny or unserious.', 'Laughing out loud.', 'lol that was wild', '["Chat","Humor"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"lol","term":"lol","category":"Internet Slang","definition":"Laughing out loud. Used to show something is funny or unserious.","coachNote":"Laughing out loud.","example":"lol that was wild","relatedTerms":["Chat","Humor"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('lol-ig', 'lol ig', 'Internet Slang', 'Laughing out loud, I guess. A casual phrase used to show mild amusement, uncertainty, awkward agreement, or reluctant acceptance.', 'Laughing out loud, I guess.', 'lol ig that works', '["Chat","Humor","Uncertainty"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"lol-ig","term":"lol ig","category":"Internet Slang","definition":"Laughing out loud, I guess. A casual phrase used to show mild amusement, uncertainty, awkward agreement, or reluctant acceptance.","coachNote":"Laughing out loud, I guess.","example":"lol ig that works","relatedTerms":["Chat","Humor","Uncertainty"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('los', 'LOS', 'Competitive Gaming', 'Line of sight: whether you can see a target to shoot or heal it.', 'Breaking line of sight behind cover is the cheapest way to stop incoming damage, and the cheapest way to lose your healer''s heals.', 'Break their LOS behind the pillar.', '["Sightline","Cover","Positioning"]'::jsonb, 'Overlay glossary seed (MetaBot.gg and Dot Esports terminology)', '/glossary', '{"id":"los","term":"LOS","category":"Competitive Gaming","definition":"Line of sight: whether you can see a target to shoot or heal it.","coachNote":"Breaking line of sight behind cover is the cheapest way to stop incoming damage, and the cheapest way to lose your healer''s heals.","example":"Break their LOS behind the pillar.","relatedTerms":["Sightline","Cover","Positioning"],"sourceName":"Overlay glossary seed (MetaBot.gg and Dot Esports terminology)","sourceUrl":"/glossary"}'::jsonb, '2026-10-26 23:38:59+00'::timestamptz),
  ('meta', 'meta', 'Competitive Gaming', 'The currently favored strategies, characters, builds, or tactics in a game.', 'What is currently considered strong or optimal.', 'that comp is meta', '["Strategy","Competitive"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"meta","term":"meta","category":"Competitive Gaming","definition":"The currently favored strategies, characters, builds, or tactics in a game.","coachNote":"What is currently considered strong or optimal.","example":"that comp is meta","relatedTerms":["Strategy","Competitive"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('mobility-build', 'Mobility Build', 'Build Theory', 'A build plan centered on movement tools, rotations, chase routes, escape paths, vertical access, and fast target swaps.', 'Mobility builds are not just about moving more. They are about arriving first, leaving safely, and forcing enemies to turn at the wrong time.', 'A Spider-Man mobility build uses web movement to scout, isolate a backline target, and reset before peel arrives.', '["Hero Build","Dive","Flanking","Scouting","Engage"]'::jsonb, 'Coach definition for Marvel Rivals build planning', '/glossary', '{"id":"mobility-build","term":"Mobility Build","category":"Build Theory","definition":"A build plan centered on movement tools, rotations, chase routes, escape paths, vertical access, and fast target swaps.","coachNote":"Mobility builds are not just about moving more. They are about arriving first, leaving safely, and forcing enemies to turn at the wrong time.","example":"A Spider-Man mobility build uses web movement to scout, isolate a backline target, and reset before peel arrives.","relatedTerms":["Hero Build","Dive","Flanking","Scouting","Engage"],"sourceName":"Coach definition for Marvel Rivals build planning","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('movement-boost', 'Movement Boost', 'Status Effect', 'A buff that increases movement speed, helping a hero rotate, chase, disengage, or cross dangerous space faster.', 'Movement boost is strongest when the team moves with the timing. Speeding in alone usually turns a good buff into an early feed.', 'A movement boost can help a team cross a long sightline before poke damage stacks up.', '["Mobility Build","Rotation","Engage","Disengage"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"movement-boost","term":"Movement Boost","category":"Status Effect","definition":"A buff that increases movement speed, helping a hero rotate, chase, disengage, or cross dangerous space faster.","coachNote":"Movement boost is strongest when the team moves with the timing. Speeding in alone usually turns a good buff into an early feed.","example":"A movement boost can help a team cross a long sightline before poke damage stacks up.","relatedTerms":["Mobility Build","Rotation","Engage","Disengage"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('mvp-svp', 'MVP/SVP', 'Competitive Gaming', 'Most Valuable Player and Second Valuable Player, awarded to the top two players in a match: MVP on the winning team, SVP on the losing team.', 'MVP and SVP reward match-end stats, not always the plays that won the fight. Use them as a signal, not a verdict.', 'She went MVP that game, 30 elims.', '["Competitive","Ranked"]'::jsonb, 'Overlay glossary seed (MetaBot.gg and Dot Esports terminology)', '/glossary', '{"id":"mvp-svp","term":"MVP/SVP","category":"Competitive Gaming","definition":"Most Valuable Player and Second Valuable Player, awarded to the top two players in a match: MVP on the winning team, SVP on the losing team.","coachNote":"MVP and SVP reward match-end stats, not always the plays that won the fight. Use them as a signal, not a verdict.","example":"She went MVP that game, 30 elims.","relatedTerms":["Competitive","Ranked"],"sourceName":"Overlay glossary seed (MetaBot.gg and Dot Esports terminology)","sourceUrl":"/glossary"}'::jsonb, '2026-10-26 23:38:59+00'::timestamptz),
  ('nerf', 'nerf', 'Competitive Gaming', 'A balance change that makes a character, weapon, ability, or strategy weaker.', 'A change that makes something weaker.', 'they nerfed that hero', '["Balance","Patch"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"nerf","term":"nerf","category":"Competitive Gaming","definition":"A balance change that makes a character, weapon, ability, or strategy weaker.","coachNote":"A change that makes something weaker.","example":"they nerfed that hero","relatedTerms":["Balance","Patch"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('nt', 'nt', 'Gaming Chat', 'Nice try. Used to encourage someone after a failed play or close round.', 'Nice try.', 'nt, we almost had it', '["Chat","Sportsmanship"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"nt","term":"nt","category":"Gaming Chat","definition":"Nice try. Used to encourage someone after a failed play or close round.","coachNote":"Nice try.","example":"nt, we almost had it","relatedTerms":["Chat","Sportsmanship"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('off-angle', 'Off-Angle', 'Coach Term', 'A side angle that pressures the enemy from somewhere other than the main team position without fully committing to a deep flank.', 'Use off-angles to split attention, then leave before the enemy can isolate you.', 'Hela taking a side balcony while her team pushes main is playing an off-angle.', '["Flanking","Poke","High Ground"]'::jsonb, 'Coach definition informed by Marvel Rivals positioning terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"off-angle","term":"Off-Angle","category":"Coach Term","definition":"A side angle that pressures the enemy from somewhere other than the main team position without fully committing to a deep flank.","coachNote":"Use off-angles to split attention, then leave before the enemy can isolate you.","example":"Hela taking a side balcony while her team pushes main is playing an off-angle.","relatedTerms":["Flanking","Poke","High Ground"],"sourceName":"Coach definition informed by Marvel Rivals positioning terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('off-healer', 'Off-Healer', 'Role', 'A Strategist archetype that provides supplemental healing while contributing more damage, utility, control, or playmaking than the team''s primary healer.', 'Off-healer does not mean ignoring injured teammates. Support the main healer, use your utility proactively, and shift back to healing when pressure spikes.', 'The off-healer helps secure a pick, then shifts back to healing when the frontline takes pressure.', '["Strategist","Support","Primary Healer","Utility Build"]'::jsonb, 'Manual glossary entry', '/glossary', '{"id":"off-healer","term":"Off-Healer","category":"Role","definition":"A Strategist archetype that provides supplemental healing while contributing more damage, utility, control, or playmaking than the team''s primary healer.","coachNote":"Off-healer does not mean ignoring injured teammates. Support the main healer, use your utility proactively, and shift back to healing when pressure spikes.","example":"The off-healer helps secure a pick, then shifts back to healing when the frontline takes pressure.","relatedTerms":["Strategist","Support","Primary Healer","Utility Build"],"sourceName":"Manual glossary entry","sourceUrl":"/glossary"}'::jsonb, '2026-07-27 08:06:05+00'::timestamptz),
  ('one-angle-rule', 'One-Angle Rule', 'Positioning', 'A cover principle where you try to expose yourself to only the angle you are actively fighting instead of several threats at once.', 'If you are shooting one target, it usually makes no sense to be visible to three other enemies. Reposition until cover blocks the extra angles.', 'Moving behind a wall so you can shoot the enemy on the right while the enemy on main cannot see you.', '["Cover","Peeking","Choke Point","Sightline"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"one-angle-rule","term":"One-Angle Rule","category":"Positioning","definition":"A cover principle where you try to expose yourself to only the angle you are actively fighting instead of several threats at once.","coachNote":"If you are shooting one target, it usually makes no sense to be visible to three other enemies. Reposition until cover blocks the extra angles.","example":"Moving behind a wall so you can shoot the enemy on the right while the enemy on main cannot see you.","relatedTerms":["Cover","Peeking","Choke Point","Sightline"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('overtime', 'Overtime', 'Objective', 'A final contest window that keeps an objective fight alive when the timer or score would otherwise end, usually because a team is still contesting.', 'Overtime is not the moment for perfect setups. Touch safely, survive, and chain resources so the team gets one more real fight.', 'A Vanguard may touch in overtime so teammates can respawn and recontest.', '["Objective","C9","Contest","Stall"]'::jsonb, 'Coach definition informed by Marvel Rivals objective modes', 'https://marvelrivals.fandom.com/wiki/Game_Modes', '{"id":"overtime","term":"Overtime","category":"Objective","definition":"A final contest window that keeps an objective fight alive when the timer or score would otherwise end, usually because a team is still contesting.","coachNote":"Overtime is not the moment for perfect setups. Touch safely, survive, and chain resources so the team gets one more real fight.","example":"A Vanguard may touch in overtime so teammates can respawn and recontest.","relatedTerms":["Objective","C9","Contest","Stall"],"sourceName":"Coach definition informed by Marvel Rivals objective modes","sourceUrl":"https://marvelrivals.fandom.com/wiki/Game_Modes"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('parallel-peek', 'Parallel Peek', 'Positioning', 'A peek where you move sideways along the cover edge instead of walking forward into the enemy sightline.', 'Parallel peeking makes you harder to hit and gives you a cleaner return path back behind cover.', 'Peeking left from a wall, firing, then strafing back behind the same wall instead of walking toward the enemy.', '["Cover","Peeking","Hitbox Minimization"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"parallel-peek","term":"Parallel Peek","category":"Positioning","definition":"A peek where you move sideways along the cover edge instead of walking forward into the enemy sightline.","coachNote":"Parallel peeking makes you harder to hit and gives you a cleaner return path back behind cover.","example":"Peeking left from a wall, firing, then strafing back behind the same wall instead of walking toward the enemy.","relatedTerms":["Cover","Peeking","Hitbox Minimization"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('passive-pressure', 'Passive Pressure', 'Map Control', 'Value created by a strong position before committing abilities, because the enemy must respect your angle, movement options, or threat.', 'Passive pressure is not passive play. You are playing aggressively with position while staying patient with cooldowns and cover.', 'Rocket Raccoon holding an off-angle can force Luna Snow to panic-use a cooldown before Rocket fully commits.', '["Power Position","Off-Angle","Cooldown Trade","Scouting"]'::jsonb, 'Power Positions guide notes', '/power-positions', '{"id":"passive-pressure","term":"Passive Pressure","category":"Map Control","definition":"Value created by a strong position before committing abilities, because the enemy must respect your angle, movement options, or threat.","coachNote":"Passive pressure is not passive play. You are playing aggressively with position while staying patient with cooldowns and cover.","example":"Rocket Raccoon holding an off-angle can force Luna Snow to panic-use a cooldown before Rocket fully commits.","relatedTerms":["Power Position","Off-Angle","Cooldown Trade","Scouting"],"sourceName":"Power Positions guide notes","sourceUrl":"/power-positions"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('peeking', 'Peeking', 'Positioning', 'Briefly exposing yourself from cover to gather information, apply pressure, or take a shot before returning to safety.', 'Peek with a purpose. Wide peeking or walking forward into the enemy sightline makes your movement easy to punish.', 'A player shoulder-peeks from a doorway, fires one shot, then returns behind the wall.', '["Cover","Parallel Peek","Hitbox Minimization","Scouting"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"peeking","term":"Peeking","category":"Positioning","definition":"Briefly exposing yourself from cover to gather information, apply pressure, or take a shot before returning to safety.","coachNote":"Peek with a purpose. Wide peeking or walking forward into the enemy sightline makes your movement easy to punish.","example":"A player shoulder-peeks from a doorway, fires one shot, then returns behind the wall.","relatedTerms":["Cover","Parallel Peek","Hitbox Minimization","Scouting"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('peel', 'peel', 'Competitive Gaming', 'To protect a teammate by pushing away, controlling, or damaging enemies who are attacking them.', 'Protecting a teammate from pressure.', 'peel for supports', '["Teamplay","Defense"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"peel","term":"peel","category":"Competitive Gaming","definition":"To protect a teammate by pushing away, controlling, or damaging enemies who are attacking them.","coachNote":"Protecting a teammate from pressure.","example":"peel for supports","relatedTerms":["Teamplay","Defense"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('peeling', 'Peeling', 'Positioning', 'Helping an ally who is under attack, usually by damaging, blocking, healing, crowd-controlling, or bodyguarding the threat.', 'Peel is not only a support job. Vanguards and Duelists should turn when the backline is being collapsed on.', 'Using a stun or shield to save Luna Snow from Spider-Man is peeling.', '["Dive","Backline","Crowd Control"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"peeling","term":"Peeling","category":"Positioning","definition":"Helping an ally who is under attack, usually by damaging, blocking, healing, crowd-controlling, or bodyguarding the threat.","coachNote":"Peel is not only a support job. Vanguards and Duelists should turn when the backline is being collapsed on.","example":"Using a stun or shield to save Luna Snow from Spider-Man is peeling.","relatedTerms":["Dive","Backline","Crowd Control"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('pit', 'Pit', 'Map Control', 'A map hazard or drop-off that can instantly eliminate players who fall into it, often making displacement abilities more dangerous nearby.', 'Fight differently near pits. Save mobility, respect knockbacks, and avoid standing where one displacement turns a won fight into a lost one.', 'Spider-Man can threaten pit kills by displacing enemies near a ledge.', '["Map Control","Displacement","Knockback","Positioning"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"pit","term":"Pit","category":"Map Control","definition":"A map hazard or drop-off that can instantly eliminate players who fall into it, often making displacement abilities more dangerous nearby.","coachNote":"Fight differently near pits. Save mobility, respect knockbacks, and avoid standing where one displacement turns a won fight into a lost one.","example":"Spider-Man can threaten pit kills by displacing enemies near a ledge.","relatedTerms":["Map Control","Displacement","Knockback","Positioning"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('placement-match', 'Placement Match', 'Ranked', 'A ranked match used near the start of a season to help determine a player''s starting rank around a projected skill level.', 'Play placements for stable habits, not desperation. A small sample rewards consistency more than risky hero swaps every fight.', 'After a new season begins, placement matches help decide where a player starts on the ranked ladder.', '["Ranked","Competitive","Ladder","Matchmaking"]'::jsonb, 'Marvel Rivals Competitive overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"placement-match","term":"Placement Match","category":"Ranked","definition":"A ranked match used near the start of a season to help determine a player''s starting rank around a projected skill level.","coachNote":"Play placements for stable habits, not desperation. A small sample rewards consistency more than risky hero swaps every fight.","example":"After a new season begins, placement matches help decide where a player starts on the ranked ladder.","relatedTerms":["Ranked","Competitive","Ladder","Matchmaking"],"sourceName":"Marvel Rivals Competitive overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('pocket-healer', 'Pocket Healer', 'Role', 'A healer who concentrates most of their attention and resources on one teammate for a period of time, usually a frontline anchor or carry.', 'Pocketing can enable a strong play, but do not abandon the rest of the team or follow the pocket target into an unwinnable position.', 'The pocket healer stays ready to support the solo Vanguard through the next engage.', '["Primary Healer","Target Priority","Frontline","Peeling"]'::jsonb, 'MarvelRivals.gg Jeff the Land Shark guide', 'https://marvelrivals.gg/jeff-the-land-shark-guide/', '{"id":"pocket-healer","term":"Pocket Healer","category":"Role","definition":"A healer who concentrates most of their attention and resources on one teammate for a period of time, usually a frontline anchor or carry.","coachNote":"Pocketing can enable a strong play, but do not abandon the rest of the team or follow the pocket target into an unwinnable position.","example":"The pocket healer stays ready to support the solo Vanguard through the next engage.","relatedTerms":["Primary Healer","Target Priority","Frontline","Peeling"],"sourceName":"MarvelRivals.gg Jeff the Land Shark guide","sourceUrl":"https://marvelrivals.gg/jeff-the-land-shark-guide/"}'::jsonb, '2026-07-27 08:06:06+00'::timestamptz),
  ('poke', 'Poke', 'Positioning', 'Dealing damage from distance, ideally from outside the enemy team''s effective range, to make engagement safer for the attacker.', 'Poke wins by patience and angle control. It loses value when forced into cramped close-range fights.', 'Hela, Phoenix, Hawkeye, Iron Man, Black Widow, Moon Knight, and Squirrel Girl are listed as poke examples.', '["Choke Point","Hitscan","Off-Angle"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"poke","term":"Poke","category":"Positioning","definition":"Dealing damage from distance, ideally from outside the enemy team''s effective range, to make engagement safer for the attacker.","coachNote":"Poke wins by patience and angle control. It loses value when forced into cramped close-range fights.","example":"Hela, Phoenix, Hawkeye, Iron Man, Black Widow, Moon Knight, and Squirrel Girl are listed as poke examples.","relatedTerms":["Choke Point","Hitscan","Off-Angle"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('power-position', 'Power Position', 'Map Control', 'A map location that gives a player or team multiple options to pressure objective, control lanes, scout enemy movement, and leave safely.', 'Do not treat a power position as a fixed camping spot. Use it to create passive pressure, force enemy cooldowns, then rotate or drop when the fight asks for it.', 'A central high-ground room that sees objective and connects to both side lanes can be a power position.', '["Lane Control","High Ground","Off-Angle","Choke Point"]'::jsonb, 'Power Positions guide notes', '/power-positions', '{"id":"power-position","term":"Power Position","category":"Map Control","definition":"A map location that gives a player or team multiple options to pressure objective, control lanes, scout enemy movement, and leave safely.","coachNote":"Do not treat a power position as a fixed camping spot. Use it to create passive pressure, force enemy cooldowns, then rotate or drop when the fight asks for it.","example":"A central high-ground room that sees objective and connects to both side lanes can be a power position.","relatedTerms":["Lane Control","High Ground","Off-Angle","Choke Point"],"sourceName":"Power Positions guide notes","sourceUrl":"/power-positions"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('practice-vs-ai', 'Practice vs. AI', 'Game Mode', 'A practice queue where players fight AI-controlled opponents using objective rules similar to standard match modes.', 'Practice vs. AI is best for learning controls, ability ranges, and map routes. Move to PvP when you need realistic pressure and punishment.', 'A beginner can use Practice vs. AI to learn how Convoy objectives move.', '["PvE","Practice","Quick Match","Objective"]'::jsonb, 'Marvel Rivals Wiki - Game Modes', 'https://marvelrivals.fandom.com/wiki/Game_Modes', '{"id":"practice-vs-ai","term":"Practice vs. AI","category":"Game Mode","definition":"A practice queue where players fight AI-controlled opponents using objective rules similar to standard match modes.","coachNote":"Practice vs. AI is best for learning controls, ability ranges, and map routes. Move to PvP when you need realistic pressure and punishment.","example":"A beginner can use Practice vs. AI to learn how Convoy objectives move.","relatedTerms":["PvE","Practice","Quick Match","Objective"],"sourceName":"Marvel Rivals Wiki - Game Modes","sourceUrl":"https://marvelrivals.fandom.com/wiki/Game_Modes"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('primary-healer', 'Primary Healer', 'Role', 'Also called a main healer, a Strategist who can provide reliable, repeatable healing as the team''s primary source of sustain through normal fights.', 'Primary healer does not mean healbot. Stabilize urgent damage first, then use your utility or damage when the team is safe enough to support the shift.', 'The primary healer keeps the frontline stable while the second Strategist contributes utility and damage.', '["Main Healer","Off-Healer","Strategist","Sustain Healer","Burst Healer"]'::jsonb, 'Marvel Rivals healer-role discussion and competitive guide usage', 'https://www.pcgamer.com/games/third-person-shooter/marvel-rivals-tier-list-best-characters/', '{"id":"primary-healer","term":"Primary Healer","category":"Role","definition":"Also called a main healer, a Strategist who can provide reliable, repeatable healing as the team''s primary source of sustain through normal fights.","coachNote":"Primary healer does not mean healbot. Stabilize urgent damage first, then use your utility or damage when the team is safe enough to support the shift.","example":"The primary healer keeps the frontline stable while the second Strategist contributes utility and damage.","relatedTerms":["Main Healer","Off-Healer","Strategist","Sustain Healer","Burst Healer"],"sourceName":"Marvel Rivals healer-role discussion and competitive guide usage","sourceUrl":"https://www.pcgamer.com/games/third-person-shooter/marvel-rivals-tier-list-best-characters/"}'::jsonb, '2026-07-27 08:06:05+00'::timestamptz)
insert into public.glossary_terms (id, term, category, definition, coach_note, example, related_terms, source_name, source_url, raw_json, updated_at) values
  ('proficiency', 'Proficiency', 'Progression', 'A hero-specific progression system where players complete challenges and earn Proficiency Points to unlock ranks and cosmetic rewards.', 'Proficiency shows time and task completion on a hero, not guaranteed decision quality. Use it as motivation, then still review fight choices.', 'A player can raise Luna Snow proficiency by completing hero challenges over many matches.', '["Hero","Challenge","Progression","Cosmetic"]'::jsonb, 'Marvel Rivals Wiki - Proficiency', 'https://marvelrivals.fandom.com/wiki/Proficiency', '{"id":"proficiency","term":"Proficiency","category":"Progression","definition":"A hero-specific progression system where players complete challenges and earn Proficiency Points to unlock ranks and cosmetic rewards.","coachNote":"Proficiency shows time and task completion on a hero, not guaranteed decision quality. Use it as motivation, then still review fight choices.","example":"A player can raise Luna Snow proficiency by completing hero challenges over many matches.","relatedTerms":["Hero","Challenge","Progression","Cosmetic"],"sourceName":"Marvel Rivals Wiki - Proficiency","sourceUrl":"https://marvelrivals.fandom.com/wiki/Proficiency"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('pun-ily', 'pun ily', 'Heard In Game', 'Usually short for "Punisher, I love you." In match chat, "Pun" refers to The Punisher and "ily" means "I love you," often expressing playful gratitude or praise.', 'Read the phrase in context because "Pun" could also be a player''s name. It is normally a friendly compliment, not a tactical call or literal romantic declaration.', 'After The Punisher wins a difficult teamfight, a teammate types, "pun ily."', '["The Punisher","ILY","Gaming Chat","Compliment"]'::jsonb, 'Manual glossary entry', '/glossary', '{"id":"pun-ily","term":"pun ily","category":"Heard In Game","definition":"Usually short for \"Punisher, I love you.\" In match chat, \"Pun\" refers to The Punisher and \"ily\" means \"I love you,\" often expressing playful gratitude or praise.","coachNote":"Read the phrase in context because \"Pun\" could also be a player''s name. It is normally a friendly compliment, not a tactical call or literal romantic declaration.","example":"After The Punisher wins a difficult teamfight, a teammate types, \"pun ily.\"","relatedTerms":["The Punisher","ILY","Gaming Chat","Compliment"],"sourceName":"Manual glossary entry","sourceUrl":"/glossary"}'::jsonb, '2026-07-28 08:09:10+00'::timestamptz),
  ('purify', 'Purify', 'Status Effect', 'A cleanse effect that removes active debuffs from a hero.', 'Purify effects are fight-saving when held for the right debuff. Do not spend them early if the enemy still has a stronger control tool available.', 'Purify can remove a dangerous debuff before an ally is focused down.', '["Cleanse","Debuff","Utility Build","Cooldown Trade"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"purify","term":"Purify","category":"Status Effect","definition":"A cleanse effect that removes active debuffs from a hero.","coachNote":"Purify effects are fight-saving when held for the right debuff. Do not spend them early if the enemy still has a stronger control tool available.","example":"Purify can remove a dangerous debuff before an ally is focused down.","relatedTerms":["Cleanse","Debuff","Utility Build","Cooldown Trade"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('pve', 'PvE', 'Game Mode', 'Player versus environment. A mode type where players fight non-player enemies rather than another player team.', 'PvE is useful for learning basic aim, movement, and ability flow, but it will not teach every habit needed against real players.', 'Practice vs. AI is a PvE-style option.', '["Practice","Arcade","PvP","Game Mode"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"pve","term":"PvE","category":"Game Mode","definition":"Player versus environment. A mode type where players fight non-player enemies rather than another player team.","coachNote":"PvE is useful for learning basic aim, movement, and ability flow, but it will not teach every habit needed against real players.","example":"Practice vs. AI is a PvE-style option.","relatedTerms":["Practice","Arcade","PvP","Game Mode"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('pvp', 'PvP', 'Game Mode', 'Player versus player. A mode type where teams or players fight against other human-controlled opponents.', 'PvP punishes predictable movement and poor timing faster than PvE. Treat scouting and cooldown discipline as part of the fundamentals.', 'Quick Match and Competitive are PvP modes.', '["Quick Match","Competitive","PvE","Team Fight"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"pvp","term":"PvP","category":"Game Mode","definition":"Player versus player. A mode type where teams or players fight against other human-controlled opponents.","coachNote":"PvP punishes predictable movement and poor timing faster than PvE. Treat scouting and cooldown discipline as part of the fundamentals.","example":"Quick Match and Competitive are PvP modes.","relatedTerms":["Quick Match","Competitive","PvE","Team Fight"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('quick-match', 'Quick Match', 'Game Mode', 'The main non-ranked queue for standard Marvel Rivals objective play, featuring modes such as Domination, Convoy, and Convergence.', 'Use Quick Match to practice heroes and map flow, but still build ranked habits: regroup, track cooldowns, and play the objective.', 'A player can practice a new Strategist in Quick Match before taking them into Competitive.', '["PvP","Competitive","Domination","Convoy"]'::jsonb, 'Marvel Rivals Wiki - Game Modes', 'https://marvelrivals.fandom.com/wiki/Game_Modes', '{"id":"quick-match","term":"Quick Match","category":"Game Mode","definition":"The main non-ranked queue for standard Marvel Rivals objective play, featuring modes such as Domination, Convoy, and Convergence.","coachNote":"Use Quick Match to practice heroes and map flow, but still build ranked habits: regroup, track cooldowns, and play the objective.","example":"A player can practice a new Strategist in Quick Match before taking them into Competitive.","relatedTerms":["PvP","Competitive","Domination","Convoy"],"sourceName":"Marvel Rivals Wiki - Game Modes","sourceUrl":"https://marvelrivals.fandom.com/wiki/Game_Modes"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('rank-bronze', 'Bronze', 'Ranked', 'One of the starting lower ranks in Marvel Rivals Competitive, below Silver.', 'Bronze climbing is mostly fundamentals: stay near cover, learn your hero''s job, group before fights, and avoid giving away free deaths.', 'A Bronze player can improve quickly by focusing on survival and simple team timing.', '["Silver","Ranked","Competitive","Ladder"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-bronze","term":"Bronze","category":"Ranked","definition":"One of the starting lower ranks in Marvel Rivals Competitive, below Silver.","coachNote":"Bronze climbing is mostly fundamentals: stay near cover, learn your hero''s job, group before fights, and avoid giving away free deaths.","example":"A Bronze player can improve quickly by focusing on survival and simple team timing.","relatedTerms":["Silver","Ranked","Competitive","Ladder"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-celestial', 'Celestial', 'Ranked', 'A high Marvel Rivals competitive rank below Eternity and above the lower ladder ranks.', 'Celestial games often demand strong role discipline. Winning usually comes from coordinated timings, not just individual outplays.', 'A Celestial support should know when to kite, peel, and save cooldowns for enemy ultimates.', '["Eternity","Ranked","Competitive","Ladder"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-celestial","term":"Celestial","category":"Ranked","definition":"A high Marvel Rivals competitive rank below Eternity and above the lower ladder ranks.","coachNote":"Celestial games often demand strong role discipline. Winning usually comes from coordinated timings, not just individual outplays.","example":"A Celestial support should know when to kite, peel, and save cooldowns for enemy ultimates.","relatedTerms":["Eternity","Ranked","Competitive","Ladder"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-diamond', 'Diamond', 'Ranked', 'A Marvel Rivals competitive rank above Platinum and below Grandmaster.', 'Diamond is where good mechanics need cleaner decisions behind them. Track ultimates, rotate with purpose, and avoid autopilot engages.', 'A Diamond team can lose a winnable match by staggering before every objective fight.', '["Platinum","Grandmaster","Ranked","Ladder"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-diamond","term":"Diamond","category":"Ranked","definition":"A Marvel Rivals competitive rank above Platinum and below Grandmaster.","coachNote":"Diamond is where good mechanics need cleaner decisions behind them. Track ultimates, rotate with purpose, and avoid autopilot engages.","example":"A Diamond team can lose a winnable match by staggering before every objective fight.","relatedTerms":["Platinum","Grandmaster","Ranked","Ladder"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-eternity', 'Eternity', 'Ranked', 'A very high Marvel Rivals rank below the One Above All leaderboard tier, where players continue accumulating points instead of moving through normal sub-tiers.', 'At Eternity, small mistakes get punished quickly. Prioritize stable hero pools, matchup knowledge, and clean mental resets between games.', 'An Eternity player is expected to understand rotations, ultimate economy, and draft pressure at a high level.', '["One Above All","OAA","Celestial","Ranked"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-eternity","term":"Eternity","category":"Ranked","definition":"A very high Marvel Rivals rank below the One Above All leaderboard tier, where players continue accumulating points instead of moving through normal sub-tiers.","coachNote":"At Eternity, small mistakes get punished quickly. Prioritize stable hero pools, matchup knowledge, and clean mental resets between games.","example":"An Eternity player is expected to understand rotations, ultimate economy, and draft pressure at a high level.","relatedTerms":["One Above All","OAA","Celestial","Ranked"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-gold', 'Gold', 'Ranked', 'A middle Marvel Rivals competitive rank above Silver and below Platinum.', 'Gold is a good place to tighten one or two core habits at a time: group before fights, use cover, and stop spending ultimates after fights are already lost.', 'A Gold player who learns to reset instead of feeding can climb without changing heroes.', '["Silver","Platinum","Ranked","Competitive"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-gold","term":"Gold","category":"Ranked","definition":"A middle Marvel Rivals competitive rank above Silver and below Platinum.","coachNote":"Gold is a good place to tighten one or two core habits at a time: group before fights, use cover, and stop spending ultimates after fights are already lost.","example":"A Gold player who learns to reset instead of feeding can climb without changing heroes.","relatedTerms":["Silver","Platinum","Ranked","Competitive"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-grandmaster', 'Grandmaster', 'Ranked', 'A high Marvel Rivals competitive rank below Celestial and above Diamond.', 'Grandmaster games usually punish loose ultimates, late rotations, and unclear target calls. Climbing here often means tightening teamfight planning.', 'A Grandmaster player should understand when to save resources for the next objective fight instead of chasing stagger kills.', '["Diamond","Celestial","Ranked","Competitive"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-grandmaster","term":"Grandmaster","category":"Ranked","definition":"A high Marvel Rivals competitive rank below Celestial and above Diamond.","coachNote":"Grandmaster games usually punish loose ultimates, late rotations, and unclear target calls. Climbing here often means tightening teamfight planning.","example":"A Grandmaster player should understand when to save resources for the next objective fight instead of chasing stagger kills.","relatedTerms":["Diamond","Celestial","Ranked","Competitive"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-oaa', 'OAA', 'Ranked', 'Short for One Above All, the highest Marvel Rivals ranked designation for top competitive players.', 'When players say OAA, they usually mean the very top end of the ladder rather than simply a strong ranked player.', 'That Duelist peaked OAA last season.', '["One Above All","Eternity","Ranked","Ladder"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-oaa","term":"OAA","category":"Ranked","definition":"Short for One Above All, the highest Marvel Rivals ranked designation for top competitive players.","coachNote":"When players say OAA, they usually mean the very top end of the ladder rather than simply a strong ranked player.","example":"That Duelist peaked OAA last season.","relatedTerms":["One Above All","Eternity","Ranked","Ladder"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-one-above-all', 'One Above All', 'Ranked', 'The top Marvel Rivals ranked designation, commonly shortened to OAA, used for the highest players at the top of the competitive ladder.', 'One Above All is a leaderboard goal, not a normal improvement benchmark. Review decisions by fight quality, then let rank follow the consistency.', 'A player chasing One Above All needs strong mechanics, hero mastery, map knowledge, and long-term ranked consistency.', '["OAA","Eternity","Ranked","Competitive"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-one-above-all","term":"One Above All","category":"Ranked","definition":"The top Marvel Rivals ranked designation, commonly shortened to OAA, used for the highest players at the top of the competitive ladder.","coachNote":"One Above All is a leaderboard goal, not a normal improvement benchmark. Review decisions by fight quality, then let rank follow the consistency.","example":"A player chasing One Above All needs strong mechanics, hero mastery, map knowledge, and long-term ranked consistency.","relatedTerms":["OAA","Eternity","Ranked","Competitive"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-platinum', 'Platinum', 'Ranked', 'A Marvel Rivals competitive rank above Gold and below higher ladder ranks such as Diamond and Celestial.', 'Platinum is where repeated fundamentals matter more: fewer stagger deaths, cleaner ultimate plans, and better adaptation to enemy win conditions.', 'A Platinum player may climb faster by reducing solo engages and improving target priority.', '["Gold","Ranked","Competitive","Ladder"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-platinum","term":"Platinum","category":"Ranked","definition":"A Marvel Rivals competitive rank above Gold and below higher ladder ranks such as Diamond and Celestial.","coachNote":"Platinum is where repeated fundamentals matter more: fewer stagger deaths, cleaner ultimate plans, and better adaptation to enemy win conditions.","example":"A Platinum player may climb faster by reducing solo engages and improving target priority.","relatedTerms":["Gold","Ranked","Competitive","Ladder"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rank-silver', 'Silver', 'Ranked', 'A Marvel Rivals competitive rank above Bronze and below Gold.', 'Silver improvement usually starts with fight structure: regroup, identify the objective, and use abilities with a reason instead of on cooldown.', 'A Silver team can win more fights by waiting for all six players before re-engaging.', '["Bronze","Gold","Ranked","Competitive"]'::jsonb, 'Marvel Rivals Wiki - Competitive', 'https://marvelrivals.fandom.com/wiki/Competitive', '{"id":"rank-silver","term":"Silver","category":"Ranked","definition":"A Marvel Rivals competitive rank above Bronze and below Gold.","coachNote":"Silver improvement usually starts with fight structure: regroup, identify the objective, and use abilities with a reason instead of on cooldown.","example":"A Silver team can win more fights by waiting for all six players before re-engaging.","relatedTerms":["Bronze","Gold","Ranked","Competitive"],"sourceName":"Marvel Rivals Wiki - Competitive","sourceUrl":"https://marvelrivals.fandom.com/wiki/Competitive"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz),
  ('rebalance', 'Rebalance', 'Competitive Gaming', 'A balance update that changes how a hero, ability, or mechanic works, often mixing buffs and nerfs rather than simply making something stronger or weaker.', 'After a rebalance, reread the kit instead of relying on old muscle memory. The hero''s job may have shifted even if the name stayed the same.', 'A patch can rebalance an ability by lowering its burst damage but adding more charges.', '["Patch","Buff","Nerf","Meta"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"rebalance","term":"Rebalance","category":"Competitive Gaming","definition":"A balance update that changes how a hero, ability, or mechanic works, often mixing buffs and nerfs rather than simply making something stronger or weaker.","coachNote":"After a rebalance, reread the kit instead of relying on old muscle memory. The hero''s job may have shifted even if the name stayed the same.","example":"A patch can rebalance an ability by lowering its burst damage but adding more charges.","relatedTerms":["Patch","Buff","Nerf","Meta"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('resource-rumble', 'Resource Rumble', 'Game Mode', 'A mode where teams fight over resource zones, drain resources from captured areas, and may unlock a final contest point depending on progress.', 'Resource Rumble is won by rotating early and controlling the next zone before the resource timer forces everyone there.', 'When the first resource zone is nearly depleted, rotate toward the next likely fight instead of overcommitting late.', '["Objective","Rotation","Point Control","Map Control"]'::jsonb, 'Marvel Rivals modes overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"resource-rumble","term":"Resource Rumble","category":"Game Mode","definition":"A mode where teams fight over resource zones, drain resources from captured areas, and may unlock a final contest point depending on progress.","coachNote":"Resource Rumble is won by rotating early and controlling the next zone before the resource timer forces everyone there.","example":"When the first resource zone is nearly depleted, rotate toward the next likely fight instead of overcommitting late.","relatedTerms":["Objective","Rotation","Point Control","Map Control"],"sourceName":"Marvel Rivals modes overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('scouting', 'Scouting', 'Coach Term', 'Gathering information about enemy location, movement, and cooldowns before committing damage, mobility, or a full engage.', 'Scout from safety before you peek or dive. Good scouting makes mechanics easier because you are not surprised by the target''s movement.', 'A Black Widow checking where Spider-Man is moving before charging and peeking for the shot.', '["Cover","Power Position","Target Priority","Engage"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"scouting","term":"Scouting","category":"Coach Term","definition":"Gathering information about enemy location, movement, and cooldowns before committing damage, mobility, or a full engage.","coachNote":"Scout from safety before you peek or dive. Good scouting makes mechanics easier because you are not surprised by the target''s movement.","example":"A Black Widow checking where Spider-Man is moving before charging and peeking for the shot.","relatedTerms":["Cover","Power Position","Target Priority","Engage"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('secondary-hero', 'Secondary Hero', 'Team-Up', 'A hero who benefits from an active Team-Up when the Anchor Hero is present, often gaining a new active or passive Team-Up ability.', 'Secondary Heroes are the payoff pieces. Pick them when your team is already committed to the anchor.', 'Scarlet Witch and Magik are Secondary Heroes in Arcane Order.', '["Anchor Hero","Team-Up Ability"]'::jsonb, 'Marvel Rivals Wiki - Team-Ups', 'https://marvelrivals.fandom.com/wiki/Team-Ups', '{"id":"secondary-hero","term":"Secondary Hero","category":"Team-Up","definition":"A hero who benefits from an active Team-Up when the Anchor Hero is present, often gaining a new active or passive Team-Up ability.","coachNote":"Secondary Heroes are the payoff pieces. Pick them when your team is already committed to the anchor.","example":"Scarlet Witch and Magik are Secondary Heroes in Arcane Order.","relatedTerms":["Anchor Hero","Team-Up Ability"],"sourceName":"Marvel Rivals Wiki - Team-Ups","sourceUrl":"https://marvelrivals.fandom.com/wiki/Team-Ups"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('sightline', 'Sightline', 'Positioning', 'A line of vision between two points that determines who can see, shoot, heal, or threaten whom.', 'Control sightlines deliberately. A strong sightline pressures enemies; a careless one exposes you to damage you are not ready to answer.', 'Holding a balcony that sees the choke creates a sightline enemies must respect before they can reach objective.', '["Cover","High Ground","Off-Angle","Lane Control"]'::jsonb, 'Strategic Cover guide notes', '/strategic-cover', '{"id":"sightline","term":"Sightline","category":"Positioning","definition":"A line of vision between two points that determines who can see, shoot, heal, or threaten whom.","coachNote":"Control sightlines deliberately. A strong sightline pressures enemies; a careless one exposes you to damage you are not ready to answer.","example":"Holding a balcony that sees the choke creates a sightline enemies must respect before they can reach objective.","relatedTerms":["Cover","High Ground","Off-Angle","Lane Control"],"sourceName":"Strategic Cover guide notes","sourceUrl":"/strategic-cover"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('silenced', 'Silenced', 'Status Effect', 'A debuff that prevents a hero from using their ultimate ability while the effect is active.', 'Silence effects are strongest against heroes who are waiting to turn the fight with an ultimate. Track likely ultimate windows before spending it.', 'Silencing a hero before they can ult can stop a fight-winning counterplay.', '["Debuff","Ult","Ultimate Charge","Cooldown Trade"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"silenced","term":"Silenced","category":"Status Effect","definition":"A debuff that prevents a hero from using their ultimate ability while the effect is active.","coachNote":"Silence effects are strongest against heroes who are waiting to turn the fight with an ultimate. Track likely ultimate windows before spending it.","example":"Silencing a hero before they can ult can stop a fight-winning counterplay.","relatedTerms":["Debuff","Ult","Ultimate Charge","Cooldown Trade"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('smurfing', 'Smurfing', 'Ranked', 'When a highly experienced or high-ranked player uses a lower-ranked or new account, often creating uneven matches for less experienced players.', 'A smurf can distort one match, but do not let it distort your review. Separate unwinnable pressure from mistakes you can actually fix.', 'A high-rank Duelist on a new account can make a low-rank lobby feel much harder than normal.', '["Ranked","Matchmaking","Inflating the Ladder","Elo"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"smurfing","term":"Smurfing","category":"Ranked","definition":"When a highly experienced or high-ranked player uses a lower-ranked or new account, often creating uneven matches for less experienced players.","coachNote":"A smurf can distort one match, but do not let it distort your review. Separate unwinnable pressure from mistakes you can actually fix.","example":"A high-rank Duelist on a new account can make a low-rank lobby feel much harder than normal.","relatedTerms":["Ranked","Matchmaking","Inflating the Ladder","Elo"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('squishies', 'Squishies', 'Competitive Gaming', 'Characters with small health pools, typically Duelists and Strategists.', 'Squishies win fights from safe angles and lose them when caught alone. Protect yours and punish theirs.', 'Protect the squishies, don''t overextend.', '["Duelist","Strategist","Peel"]'::jsonb, 'Overlay glossary seed (MetaBot.gg and Dot Esports terminology)', '/glossary', '{"id":"squishies","term":"Squishies","category":"Competitive Gaming","definition":"Characters with small health pools, typically Duelists and Strategists.","coachNote":"Squishies win fights from safe angles and lose them when caught alone. Protect yours and punish theirs.","example":"Protect the squishies, don''t overextend.","relatedTerms":["Duelist","Strategist","Peel"],"sourceName":"Overlay glossary seed (MetaBot.gg and Dot Esports terminology)","sourceUrl":"/glossary"}'::jsonb, '2026-10-26 23:38:59+00'::timestamptz),
  ('stealth', 'Stealth', 'Status Effect', 'A state where a hero becomes invisible or much harder for enemies to see, usually to scout, reposition, or set up an attack.', 'Stealth creates first-look advantage, not guaranteed safety. Use it to choose a better angle and exit path before committing.', 'A stealth hero can scout a backline route before starting a flank.', '["Scouting","Flanking","Off-Angle","Target Priority"]'::jsonb, 'Marvel Rivals Wiki - Status Effects', 'https://marvelrivals.fandom.com/wiki/Status_Effects', '{"id":"stealth","term":"Stealth","category":"Status Effect","definition":"A state where a hero becomes invisible or much harder for enemies to see, usually to scout, reposition, or set up an attack.","coachNote":"Stealth creates first-look advantage, not guaranteed safety. Use it to choose a better angle and exit path before committing.","example":"A stealth hero can scout a backline route before starting a flank.","relatedTerms":["Scouting","Flanking","Off-Angle","Target Priority"],"sourceName":"Marvel Rivals Wiki - Status Effects","sourceUrl":"https://marvelrivals.fandom.com/wiki/Status_Effects"}'::jsonb, '2026-07-06 13:24:32+00'::timestamptz)
insert into public.glossary_terms (id, term, category, definition, coach_note, example, related_terms, source_name, source_url, raw_json, updated_at) values
  ('strategist', 'Strategist', 'Role', 'The Marvel Rivals support role. Strategists help teammates through healing, buffs, utility, damage support, and fight-saving cooldowns.', 'Strategists are not heal bots. Their cooldown timing, survival, and utility often decide whether a team can reset, re-engage, or survive an ultimate.', 'Luna Snow, Mantis, and Rocket Raccoon are Strategists.', '["Support","Backline","Utility Build","Peeling"]'::jsonb, 'Marvel Rivals gameplay overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"strategist","term":"Strategist","category":"Role","definition":"The Marvel Rivals support role. Strategists help teammates through healing, buffs, utility, damage support, and fight-saving cooldowns.","coachNote":"Strategists are not heal bots. Their cooldown timing, survival, and utility often decide whether a team can reset, re-engage, or survive an ultimate.","example":"Luna Snow, Mantis, and Rocket Raccoon are Strategists.","relatedTerms":["Support","Backline","Utility Build","Peeling"],"sourceName":"Marvel Rivals gameplay overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:30+00'::timestamptz),
  ('support', 'Support', 'Role', 'A common player term used interchangeably with Strategist.', 'Support does not only mean healing. Strategists often bring tempo tools, control, damage boosts, and fight-saving ultimates.', 'Luna Snow, Mantis, and Rocket Raccoon are Strategists.', '["Strategist","Peeling","Backline"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"support","term":"Support","category":"Role","definition":"A common player term used interchangeably with Strategist.","coachNote":"Support does not only mean healing. Strategists often bring tempo tools, control, damage boosts, and fight-saving ultimates.","example":"Luna Snow, Mantis, and Rocket Raccoon are Strategists.","relatedTerms":["Strategist","Peeling","Backline"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('sustain', 'Sustain', 'Combat', 'A hero''s ability to stay alive through health, self-healing, shields, damage reduction, or repeated support.', 'High sustain lets a team hold space longer, but burst damage or anti-heal timing can still break it.', 'A Vanguard with high health and defensive cooldowns has strong sustain.', '["Brawl","Tank","Support"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"sustain","term":"Sustain","category":"Combat","definition":"A hero''s ability to stay alive through health, self-healing, shields, damage reduction, or repeated support.","coachNote":"High sustain lets a team hold space longer, but burst damage or anti-heal timing can still break it.","example":"A Vanguard with high health and defensive cooldowns has strong sustain.","relatedTerms":["Brawl","Tank","Support"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('sustain-build', 'Sustain Build', 'Build Theory', 'A build plan that emphasizes staying power through healing, shields, armor, damage reduction, revive value, or repeated defensive resources.', 'Sustain builds are strongest when they help your team hold or retake space. They lose value if the team only survives without creating pressure.', 'A Groot sustain build focuses on walls, body blocking, and cover cycling so allies can stabilize and keep fighting.', '["Hero Build","Sustain","Brawl","Frontline","Utility Build"]'::jsonb, 'Coach definition for Marvel Rivals build planning', '/glossary', '{"id":"sustain-build","term":"Sustain Build","category":"Build Theory","definition":"A build plan that emphasizes staying power through healing, shields, armor, damage reduction, revive value, or repeated defensive resources.","coachNote":"Sustain builds are strongest when they help your team hold or retake space. They lose value if the team only survives without creating pressure.","example":"A Groot sustain build focuses on walls, body blocking, and cover cycling so allies can stabilize and keep fighting.","relatedTerms":["Hero Build","Sustain","Brawl","Frontline","Utility Build"],"sourceName":"Coach definition for Marvel Rivals build planning","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('sustain-healer', 'Sustain Healer', 'Role', 'A healer built around steady, repeatable healing that keeps allies stable through prolonged pressure rather than relying only on large emergency bursts.', 'Sustain healing works best before health bars collapse. Maintain uptime, but tell allies to use cover because steady healing may not beat concentrated burst damage.', 'A sustain healer keeps healing active through a long frontline trade.', '["Primary Healer","Burst Healer","Healing Over Time","Sustain"]'::jsonb, 'MarvelRivals.gg Strategist healing analysis', 'https://marvelrivals.gg/ultron-guide/', '{"id":"sustain-healer","term":"Sustain Healer","category":"Role","definition":"A healer built around steady, repeatable healing that keeps allies stable through prolonged pressure rather than relying only on large emergency bursts.","coachNote":"Sustain healing works best before health bars collapse. Maintain uptime, but tell allies to use cover because steady healing may not beat concentrated burst damage.","example":"A sustain healer keeps healing active through a long frontline trade.","relatedTerms":["Primary Healer","Burst Healer","Healing Over Time","Sustain"],"sourceName":"MarvelRivals.gg Strategist healing analysis","sourceUrl":"https://marvelrivals.gg/ultron-guide/"}'::jsonb, '2026-07-27 08:06:05+00'::timestamptz),
  ('tank', 'Tank', 'Role', 'A common player term used interchangeably with Vanguard.', 'When someone asks for a tank, they usually mean a Vanguard who can start fights, protect space, or absorb pressure.', 'Hulk, Groot, and Doctor Strange are Vanguards.', '["Vanguard","Brawl","Sustain"]'::jsonb, 'Marvel Rivals Wiki - Gameplay Terms', 'https://marvelrivals.fandom.com/wiki/Gameplay_Terms', '{"id":"tank","term":"Tank","category":"Role","definition":"A common player term used interchangeably with Vanguard.","coachNote":"When someone asks for a tank, they usually mean a Vanguard who can start fights, protect space, or absorb pressure.","example":"Hulk, Groot, and Doctor Strange are Vanguards.","relatedTerms":["Vanguard","Brawl","Sustain"],"sourceName":"Marvel Rivals Wiki - Gameplay Terms","sourceUrl":"https://marvelrivals.fandom.com/wiki/Gameplay_Terms"}'::jsonb, '2026-07-06 13:24:26+00'::timestamptz),
  ('target-priority', 'Target Priority', 'Combat', 'The decision of which enemy should be pressured first based on isolation, cooldowns, health, position, and fight win condition.', 'The best target is not always the closest target. Look for enemies who are exposed, low-resource, or already forced to look away.', 'Punishing a Strategist who used mobility early can be better than shooting a full-health Vanguard.', '["Engage","Scouting","Cooldown Trade","Dive"]'::jsonb, 'Coach definition from tutorial library', '/techniques', '{"id":"target-priority","term":"Target Priority","category":"Combat","definition":"The decision of which enemy should be pressured first based on isolation, cooldowns, health, position, and fight win condition.","coachNote":"The best target is not always the closest target. Look for enemies who are exposed, low-resource, or already forced to look away.","example":"Punishing a Strategist who used mobility early can be better than shooting a full-health Vanguard.","relatedTerms":["Engage","Scouting","Cooldown Trade","Dive"],"sourceName":"Coach definition from tutorial library","sourceUrl":"/techniques"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('team-up', 'Team-Up', 'Team-Up', 'A Marvel Rivals mechanic where specific heroes combine powers to grant buffs, extra abilities, or passive effects.', 'Treat Team-Ups as draft incentives, not automatic win conditions. The comp still needs frontline, damage, healing, and map control.', 'Planet X Pals lets Rocket Raccoon and Jeff the Land Shark ride on Groot.', '["Anchor Hero","Secondary Hero","Team-Up Ability"]'::jsonb, 'Marvel Rivals Wiki - Team-Ups', 'https://marvelrivals.fandom.com/wiki/Team-Ups', '{"id":"team-up","term":"Team-Up","category":"Team-Up","definition":"A Marvel Rivals mechanic where specific heroes combine powers to grant buffs, extra abilities, or passive effects.","coachNote":"Treat Team-Ups as draft incentives, not automatic win conditions. The comp still needs frontline, damage, healing, and map control.","example":"Planet X Pals lets Rocket Raccoon and Jeff the Land Shark ride on Groot.","relatedTerms":["Anchor Hero","Secondary Hero","Team-Up Ability"],"sourceName":"Marvel Rivals Wiki - Team-Ups","sourceUrl":"https://marvelrivals.fandom.com/wiki/Team-Ups"}'::jsonb, '2026-07-06 13:24:25+00'::timestamptz),
  ('throwing', 'throwing', 'Competitive Gaming', 'Playing in a way that causes your team to lose, either intentionally or through very reckless decisions.', 'Use this carefully. A bad play is not always throwing; look for repeated choices that ignore the team''s win condition.', 'stop throwing and group before the next fight', '["Competitive","Behavior","Inting","Tilted"]'::jsonb, 'Manual glossary entry', '/glossary', '{"id":"throwing","term":"throwing","category":"Competitive Gaming","definition":"Playing in a way that causes your team to lose, either intentionally or through very reckless decisions.","coachNote":"Use this carefully. A bad play is not always throwing; look for repeated choices that ignore the team''s win condition.","example":"stop throwing and group before the next fight","relatedTerms":["Competitive","Behavior","Inting","Tilted"],"sourceName":"Manual glossary entry","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('tilted', 'tilted', 'Competitive Gaming', 'Frustrated enough that emotions are hurting decision-making.', 'Frustrated and playing worse because of it.', 'I am tilted after that loss', '["Mindset","Competitive"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"tilted","term":"tilted","category":"Competitive Gaming","definition":"Frustrated enough that emotions are hurting decision-making.","coachNote":"Frustrated and playing worse because of it.","example":"I am tilted after that loss","relatedTerms":["Mindset","Competitive"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz),
  ('ult', 'ult', 'Competitive Gaming', 'Short for ultimate ability, usually a powerful ability charged over time.', 'Ultimate ability.', 'save ult for next fight', '["Ability","Combat"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"ult","term":"ult","category":"Competitive Gaming","definition":"Short for ultimate ability, usually a powerful ability charged over time.","coachNote":"Ultimate ability.","example":"save ult for next fight","relatedTerms":["Ability","Combat"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('ultimate-build', 'Ultimate Build', 'Build Theory', 'A build plan focused on charging, protecting, and converting a hero''s ultimate into a fight-winning timing window.', 'Ultimate builds should not hold the whole team hostage. Use regular cooldowns to force enemy answers first, then spend the ultimate when follow-up is ready.', 'A Luna Snow ultimate build plays safe before the enemy engage, then uses Fate of Both Worlds to swing the committed fight.', '["Hero Build","Engage","Cooldown Trade","Sustain Build","Utility Build"]'::jsonb, 'Coach definition for Marvel Rivals build planning', '/glossary', '{"id":"ultimate-build","term":"Ultimate Build","category":"Build Theory","definition":"A build plan focused on charging, protecting, and converting a hero''s ultimate into a fight-winning timing window.","coachNote":"Ultimate builds should not hold the whole team hostage. Use regular cooldowns to force enemy answers first, then spend the ultimate when follow-up is ready.","example":"A Luna Snow ultimate build plays safe before the enemy engage, then uses Fate of Both Worlds to swing the committed fight.","relatedTerms":["Hero Build","Engage","Cooldown Trade","Sustain Build","Utility Build"],"sourceName":"Coach definition for Marvel Rivals build planning","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('ultimate-charge', 'Ultimate Charge', 'Combat', 'Progress toward a hero''s ultimate ability, built over time and through combat actions until the ultimate becomes available.', 'Track ultimate charge by fight rhythm. If the enemy used several high-value cooldowns and won a long fight, expect ultimates soon.', 'Feeding before a regroup can give enemies extra ultimate charge for the next fight.', '["Ultimate Build","Ult","Team Fight","Cooldown Trade"]'::jsonb, 'Marvel Rivals gameplay overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"ultimate-charge","term":"Ultimate Charge","category":"Combat","definition":"Progress toward a hero''s ultimate ability, built over time and through combat actions until the ultimate becomes available.","coachNote":"Track ultimate charge by fight rhythm. If the enemy used several high-value cooldowns and won a long fight, expect ultimates soon.","example":"Feeding before a regroup can give enemies extra ultimate charge for the next fight.","relatedTerms":["Ultimate Build","Ult","Team Fight","Cooldown Trade"],"sourceName":"Marvel Rivals gameplay overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:31+00'::timestamptz),
  ('utility-build', 'Utility Build', 'Build Theory', 'A build plan that prioritizes a hero''s non-damage fight tools: crowd control, revive, shields, walls, cleanse-like saves, scouting, disruption, damage boosts, or cooldown denial.', 'A utility build asks, ''What tool wins the fight if I keep it for the right moment?'' You play around timing, line of sight, and cooldown discipline instead of spending every ability for raw damage.', 'An Adam Warlock utility build protects Karmic Revival and Soul Bond timing so the team can survive burst and re-engage.', '["Hero Build","Cooldown Trade","Peeling","Crowd Control","Sustain Build"]'::jsonb, 'Coach definition for Marvel Rivals build planning', '/glossary', '{"id":"utility-build","term":"Utility Build","category":"Build Theory","definition":"A build plan that prioritizes a hero''s non-damage fight tools: crowd control, revive, shields, walls, cleanse-like saves, scouting, disruption, damage boosts, or cooldown denial.","coachNote":"A utility build asks, ''What tool wins the fight if I keep it for the right moment?'' You play around timing, line of sight, and cooldown discipline instead of spending every ability for raw damage.","example":"An Adam Warlock utility build protects Karmic Revival and Soul Bond timing so the team can survive burst and re-engage.","relatedTerms":["Hero Build","Cooldown Trade","Peeling","Crowd Control","Sustain Build"],"sourceName":"Coach definition for Marvel Rivals build planning","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:27+00'::timestamptz),
  ('vanguard', 'Vanguard', 'Role', 'The Marvel Rivals frontline role. Vanguards usually have larger health pools, defensive tools, and space-making abilities that let a team start or survive fights.', 'A Vanguard''s job is not only to soak damage. Good Vanguard play creates timing, cover, and pressure so allies can safely deal damage or heal.', 'Doctor Strange, Groot, and Venom are Vanguards.', '["Tank","Frontline","Sustain","Engage"]'::jsonb, 'Marvel Rivals gameplay overview', 'https://en.wikipedia.org/wiki/Marvel_Rivals', '{"id":"vanguard","term":"Vanguard","category":"Role","definition":"The Marvel Rivals frontline role. Vanguards usually have larger health pools, defensive tools, and space-making abilities that let a team start or survive fights.","coachNote":"A Vanguard''s job is not only to soak damage. Good Vanguard play creates timing, cover, and pressure so allies can safely deal damage or heal.","example":"Doctor Strange, Groot, and Venom are Vanguards.","relatedTerms":["Tank","Frontline","Sustain","Engage"],"sourceName":"Marvel Rivals gameplay overview","sourceUrl":"https://en.wikipedia.org/wiki/Marvel_Rivals"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('wood-players', 'wood players', 'Competitive Gaming', 'A likely insult for very low-rank or low-skill players. It is similar to calling someone "bronze" or "low elo," but with "wood" implying a rank below normal competitive tiers.', 'Trash talk for very low-rank or low-skill players.', 'wood players need help', '["Chat","Trash Talk","Rank"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"wood-players","term":"wood players","category":"Competitive Gaming","definition":"A likely insult for very low-rank or low-skill players. It is similar to calling someone \"bronze\" or \"low elo,\" but with \"wood\" implying a rank below normal competitive tiers.","coachNote":"Trash talk for very low-rank or low-skill players.","example":"wood players need help","relatedTerms":["Chat","Trash Talk","Rank"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('wood-players-need-cas-to-get-dope', '#wood players need cas to get dope', 'Heard In Game', 'Likely a trash-talk phrase aimed at lower-skill players. In context, it probably means "low-rank players need casual matches, carry help, or easy lobbies to get good rewards or look good." The wording is not standard, so treat it as heard-in-game slang rather than a fixed gaming term.', 'Likely trash talk about lower-skill players needing easy help to get good results.', '#wood players need cas to get dope', '["Chat","Trash Talk","Rank","Uncertain"]'::jsonb, 'User heard in game', '/glossary', '{"id":"wood-players-need-cas-to-get-dope","term":"#wood players need cas to get dope","category":"Heard In Game","definition":"Likely a trash-talk phrase aimed at lower-skill players. In context, it probably means \"low-rank players need casual matches, carry help, or easy lobbies to get good rewards or look good.\" The wording is not standard, so treat it as heard-in-game slang rather than a fixed gaming term.","coachNote":"Likely trash talk about lower-skill players needing easy help to get good results.","example":"#wood players need cas to get dope","relatedTerms":["Chat","Trash Talk","Rank","Uncertain"],"sourceName":"User heard in game","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:29+00'::timestamptz),
  ('wp', 'wp', 'Gaming Chat', 'Well played. A compliment for a good move, round, or match.', 'Well played.', 'wp on point', '["Chat","Sportsmanship"]'::jsonb, 'Manual seed data', '/glossary', '{"id":"wp","term":"wp","category":"Gaming Chat","definition":"Well played. A compliment for a good move, round, or match.","coachNote":"Well played.","example":"wp on point","relatedTerms":["Chat","Sportsmanship"],"sourceName":"Manual seed data","sourceUrl":"/glossary"}'::jsonb, '2026-07-06 13:24:28+00'::timestamptz)
insert into public.external_sources (source_key, source_name, url, payload, fetched_at, status, error) values
  ('fandom-battlepasses', 'Marvel Rivals Fandom BattlePasses', 'https://marvelrivals.fandom.com/api.php?action=parse&page=BattlePasses&prop=wikitext&format=json&origin=*', '{"parse":{"title":"BattlePasses","pageid":11051,"wikitext":{"*":"{{DISPLAYTITLE:BattlePass}}\n[[File:S1 battlepass (1).png|thumb|313x313px|Season 1 BattlePass]]\nThe ''''''BattlePass'''''' is a seasonal item bundle in Marvel Rivals, which grants the player rewards such as [[Costumes]], [[Nameplates]], [[Emotes]], and [[Sprays]] in exchange for [[Chrono Tokens|''''''Chrono Tokens'''''']] [[File:Chrono Token Currency Icon.png|15x15px|link=|Units]].\n\n== BattlePasses ==\nA BattlePass is released to correspond with each [[Seasons|Season]] and are available for the duration of their season.. The released BattlePasses include:\n*[[Season 0: Dooms'' Rise]] - ''''''[[Chronovium (Battle Pass)|Chronovium]]''''''\n*[[Season 1: Eternal Night Falls]] - ''''''[[Darkhold (Battlepass)|Darkhold]]''''''\n*[[Season 2: Hellfire Gala]] - ''''''[[Flower Of Krakoa (BattlePass)|Flower Of Krakoa]]''''''\n*[[Season 3: The Abyss Awakens]] - ''''''[[Power of The Phoenix (BattlePass)|Power of The Phoenix]]''''''\n*[[Season 4: Heart of the Dragon]] - ''''''[[Fruit of Immortality (BattlePass)|Fruit of Immortality]]''''''\n*[[Season 5: Love is a Battlefield]] - ''''''[[Grand Garden Adventure (BattlePass)|Grand Garden Adventure]]''''''\n*[[Season 6: Night at the Museum]] - ''''''[[Museum Ticket (BattlePass)|Museum Ticket]]''''''\n*[[Season 7: The Hunt Is On]] - [[Tablet of Life and Time (BattlePass)|''''''Tablet of Life and Time'''''']]\n*[[Season 8: Sins of Alchemax]] - ''''''[[Project Heroic Age (BattlePass)|Project: Heroic Age]]''''''\n\n== Pricing ==\nThe ''''''BattlePass'''''' has 3 tiers: Free, Luxury, and Upgraded Luxury. The Free tier is free but not all rewards can be unlocked. The Luxury tier costs ''''''990 Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]] (as of Season 1) and gives access to unlock all of the rewards. The Upgraded Luxury tier costs ''''''2100 Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]] (as of Season 1) and gives access to unlock all of the rewards, as well as ''''''2800 Chrono Tokens'''''' [[File:Chrono_Token_Currency_Icon.png|link=|15x15px|Units]] and a 20% Acquisition Bonus to all ''''''Chrono Tokens'''''' [[File:Chrono_Token_Currency_Icon.png|link=|15x15px|Units]] earned. Once a Luxury ''''''BattlePass'''''' is purchased, it <u>never expires</u>, so rewards from a previously purchased ''''''BattlePass'''''' can be unlocked during a future season if it was not completed.\n{| class=\"wikitable\"\n! style=\"width:15%\" |TIER\n! style=\"width:10%\" |PRICE<br><small>(SEASON 1 ONWARDS)</small>\n! style=\"width:10%\" |[[File:Luxury_Lock_Icon.png|link=|10x10px|Luxury BattlePass Required]] LUXURY REWARDS\n! style=\"width:10%\" |<small>ACCESS TO PREVIOUS BATTLEPASSES</small>\n! style=\"width:10%\" |<small>CONVERTING CHRONO TOKENS TO UNITS</small>\n! style=\"width:15%\" |<small>EXTRA 2800 CHRONO TOKENS [[File:Chrono_Token_Currency_Icon.png|link=|15x15px|Units]] + 20% CHRONO TOKEN [[File:Chrono_Token_Currency_Icon.png|link=|15x15px|Units]] ACQUISITION BONUS</small>\n|-\n|<center>Free</center>\n|<center>''''''Free''''''</center>\n|\n|\n|\n|\n|-\n|<center>Luxury</center>\n|<center>''''''990<br>Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]]</center>\n|<center>✔</center>\n|<center>✔</center>\n|<center>✔</center>\n|-\n|<center>Upgraded Luxury</center>\n|<center>''''''2100<br>Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]]</center>\n|<center>✔</center>\n|<center>✔</center>\n|<center>✔</center>\n|<center>✔</center>\n|}\n<u>Note</u>: For Season 0, the ''''''BattlePass'''''' ([[Chronovium (Battle Pass)|''''''Chronovium'''''']]) Luxury tier cost ''''''490 Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]], and the Upgraded Luxury tier cost ''''''1050 Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]]. These prices reflected the season''s shorter duration, which was approximately half the length of a typical season, resulting in a correspondingly shorter ''''''BattlePass''''''.\n\n== Reruns ==\nReruns are when a BattlePass from a previous season is made available again for a limited-time at an increased price (at least 20% higher). All of the rewards require purchasing the Luxury BattlePass during a rerun and the Upgraded Luxury tier is not available.\n\nThe reruns  [[Chronovium (Battle Pass)|''''''Chronovium BattlePass'''''']] was made available to purchase again from during [[Season 2: Hellfire Gala|Season 2.5]] from 5/15/25 to 5/29/25 for ''''''590 Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]]. Other returning ''''''BattlePasses'''''' will be priced at ''''''1190 Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]].\n\n* [[Season 2: Hellfire Gala]] - ''''''[[Chronovium (Battle Pass)|Chronovium]] Rerun'''''' (5/15/25 - 5/29/25)\n** Priced at ''''''590 Lattice'''''' [[File:Lattice_Currency_Icon.png|link=|17x17px|Units]] since the ''''''[[Chronovium (Battle Pass)|Chronovium]] Battlepass'''''' was shorter than later BattlePasses\n* [[Season 5: Love is a Battlefield]] - [[Darkhold (BattlePass)|''''''Darkhold'''''']] ''''''Rerun'''''' (11/27/25 - 12/11/25)\n*[[Season 7: The Hunt Is On]] - ''''''[[Flower of Krakoa (BattlePass)|Flower of Krakoa]] Rerun'''''' (4/17/26 - 4/30/26)\n\n== Reality Link Point ==\n[[File:Reality Link Point Icon.png|thumb|133x133px]]\nPrevious BattlePasses can be accessed in the Reality Link Point. Go to the BATTLEPASS tab and click the icon in the top right that says NEXUS. Additionally, on this screen, Galacta''s outfit can be customized with [[Galacta Styles]]. \n{{clr}}\n\n== Gallery ==\n<gallery>\nFile:Reality Link Point.png|Reality Link Point\nFile:Season 0 Battlepass Rivals.png\nFile:Marvel Rivals Season 1 BattlePass.jpg\nFile:Marvel Rivals Season 2 BattlePass.jpg\nFile:S0 Battlepass Limited-Time Return.webp\nFile:Marvel Rivals Season 3 BattlePass.jpg\nFile:Marvel Rivals Season 4 BattlePass.jpg\nFile:Marvel Rivals Season 5 BattlePass.jpg\nFile:Season 1 BattlePass Rereun 2025.png\nFile:Marvel Rivals Season 6 BattlePass.png\nFile:Season 7 BattlePass Preview.png\nFile:Marvel Rivals Season 8 BattlePass.jpg\n</gallery>\n\n== See Also ==\n*[[Event Pass]]\n\n[[Category:Cosmetics]]\n{{DEFAULTSORT:Battlepass}}\n[[Category:BattlePass]]"}}}'::jsonb, '2026-06-20T08:01:45.423Z'::timestamptz, 'success', null),
  ('fandom-deadpool', 'Marvel Rivals Fandom Deadpool', 'https://marvelrivals.fandom.com/api.php?action=parse&page=Deadpool&prop=wikitext&format=json&origin=*', '{"parse":{"title":"Deadpool","pageid":932,"wikitext":{"*":"{{HeroTabs}}\n{{infobox Character\n| image = Deadpool Full Hero Portrait.png\n| realname = Wade Winston Wilson\n| aliases = Merc with a Mouth<br>[[Monster King]]<br>Dadpool\n| birthplace  = Regina, Saskatchewan\n| gender = Male\n| eyes = \n| hair = Bald \n| relatives =\n*Thomas Wilson <small>(father)</small><ref name=\"idle\"/><br>\n*Hailey Wilson <small>(mother)</small><ref name=\"idle\"/><br>\n*Vanessa Carlysle <small>(ex-fiancé)</small><ref name=\"idle\">''''''IDLE:'''''' \"Yeah, so Marvel Rivals — great game, everybody''s playing it. My parents know about it; my mom''s into it, my dad''s kind of interested, not really. Um… but Vanessa, what are—what are we thinking? Do you think she''ll take me back!? I mean, look, I know it''s kind of new, mixing the MCU, Marvel Rivals, comics and all that… but I just—I just want her to know what she''s missing.\"</ref>\n*Elleanor Camacho <small>(daughter)</small><br> \n*[[Minor Characters#Broodpool|Broodpool]] <small>(son)</small>\n*[[Jeff the Land Shark]] <small>(pet)</small>\n| type = Playable\n| role = [[File:Vanguard Icon.png|20px]]Vanguard<br>[[File:Duelist Icon.png|20px]]Duelist<br>[[File:Strategist Icon.png|20px]]Strategist\n| health = [[File:Vanguard Icon.png|20px]]500<br>[[File:Duelist Icon.png|20px]]275<br>[[File:Strategist Icon.png|20px]]250\n| difficulty = 0\n| team = \n| affiliation = {{Affiliation|XM}}<br>[[X-Force]]\n| voiceactor = [[Alejandro Saab]] <small>(English)</small><br>Lengquan Yuyue <small>(Chinese)</small><br>Fukushi Ochiai <small>(Japanese)</small>\n| category = no\n| imagecaption = <choose uncached><option>\"My strategy? Dive first and GG no heal. Duh.\"</option> <option>\"With me on the front lines, we can''t lose! Heh, you know, unless we do…\"</option> <option>\"You know, I just don''t get why everyone hates on Duelist mains… I mean, come on.\"</option></choose>\n| powers/skills = * Superhuman strength, speed, durability, stamina, agility, and reflexes<br>\n* Genetically enhanced physiology<br>\n*Swordsmanship\n* Regenerative healing factor<br>\n* Extended longevity<br>\n* Master martial artist, marksman and assassin<br>\n* Fourth wall breaks \n| signature = Deadpool\n| youtube = 6Y1sQPyhz5s\n| id = 1057\n| title = [[File:Deadpool Hero Logo.png|40x40px]]Deadpool}}\n\n{{Quote|Wade Wilson is the full package (or so he claims), with devastating damage output, an impenetrable shield, and swift healing. There''s no limit to what Deadpool can achieve, as long as he keeps his moves flashy! And, of course, every epic attack comes with an endless barrage of witty banter! |Official Description}}\n\n''''''Deadpool'''''' is a Multi-Role [[Heroes|hero]] for ''''[[Marvel Rivals]]'''' and is the 46th hero introduced to the game''s roster during [[Season 6: Night at the Museum]]. He is the first ''''''[[:Category:Multi-Role|Multi-Role]]'''''' hero added to the game. \n\n<p style=\"margin-bottom: 0px;\">He currently has one team-up ability:</p>\n* [[File:Mr. Pool''s Interdimensional Toy Box.png|25px]] ''''''[[Mr. Pool''s Interdimensional Toy Box]]'''''' — <span style=\"color: orange;\">''''''Anchor Hero''''''</span> [[File:Team-Up Anchor Icon.png]] for [[Elsa Bloodstone]] and [[Jeff the Land Shark]]\n\n== Overview ==\n=== Strengths ===\n* A versatile hybrid ranged and melee combatant who can upgrade his abilities mid-match, and can be played as a Vanguard, Duelist or Strategist, allowing him to fit into any team-composition.\n** Each one of Deadpool''s roles technically count as a separate character.\n*** Deadpool has different stats per role.\n*** In the [[Competitive|Competitive Mode]], each Deadpool role must be banned separately.\n* Deadpool has two passives:\n** Healing Factor provides Deadpool with a healing-over-time effect of 25 per second if he has been out of combat for 5 seconds.\n*** This passive will automatically activate if he takes more than 200 damage within a 2-second window; during this, the effect is 50 per second instead. He will also become immune to damage for a brief duration, making him practically immune to one-shot abilities. This has a 45 second cooldown.\n** Maximum Flair is tied to Deadpool''s Ultimate activation; unlike other characters, he doesn''t generate Ultimate charge over-time, instead gainining \"Style Points\" depending on his actions. Whenever he hits an enemy or heals an ally, he gains Style Points, starting on on rank E, and once it reaches rank S, he can activate his Ultimate.\n*** He gains the most amount of Style Points when he lands his abilities in quick succession.\n* Actions taken in combat grant Deadpool experience points, shown as a red gauge underneath his health; once this gauge is filled, Deadpool can upgrade one of his abilities, empowering them.\n** Although ability upgrades are unique to each role, Deadpool''s experience gauge is shared across all three variants. This means that if a player swaps roles mid-match, the specific ability upgrades will reset, but all earned experience is retained, allowing the player to immediately re-allocate their upgrade points to the new role''s skills.\n* Deadpool has two primary weapons in all three of his roles:\n** Dual Desert Eagles fire hitscan bullets with moderate damage and fast attack speed.\n*** When upgraded, every shot charges up an icon that once full, will launch an explosive projectile with a slow projectile speed. Deadpool also gains increased max ammo.\n** Kick@$$ Katanas is a melee weapon with a very fast attack speed. The second strike is a fast jab attack that can easily prove to be the brute of his damage.\n*** When upgraded, the jab strike can deal critical damage. Bouncing off an enemy with the double jump will guarentee a jab strike as well, enhancing his offensive capabilities.\n* Deadpool In Your Area is an ability for all roles: Deadpool creates a zone around himself for 5 seconds that clutters the screen of nearby enemies and deals continous damage. The taunt effect is removed once Deadpool suffers enough damage.\n** When upgraded, for all roles, enemies have their health bar taped over if they stay in the area for too long.\n* Deadpool can choose to take a selfie with enemies he lands a final blow on before they respawn, granting additional XP. While doing so, Deadpool cannot be damaged and is immune to crowd control.\n\n==== Vanguard ====\n* As a Vanguard, Deadpool trades in high damage/healing output for greater survivability and team utility, gaining double the max health.\n* His secondary fire with the desert eagles, Magical Unicorn Shield, lobs a plushie barrier at the target location that can be used to block enemy fire.\n** Similarly to other shield-type abilities, Magical Unicorn Shield can block enemy line-of-sight, as well sustain damage from any ability in the game, including Ultimate abilities such as [[Iron Man]]''s Invincible Iron Cannon and [[Scarlet Witch]]''s Reality Erasure.\n** When upgraded, the plushie becomes golden; gaining increased health and size.\n* His secondary fire with the katanas, Hazardous Hijinx, has Deadpool dash forward and slash enemies upon collision. On hit, a 5-second window is enabled where this ability can be chained up to two more times before going on cooldown.\n** When upgraded, this ability gains an additional charge and Deadpool will bounce in the air after landing a hit.\n* Deadpool In Your Area grants increased attack speed to Deadpool and nearby allies.\n** When upgraded, the ability also provides damage reduction (40% to Deadpool, and 20% to affected allies).\n* Bunny Bounce is a basic double jump with a 6 second cooldown.\n** The cooldown is instantly refreshes when the player jumps off a wall or enemy while The Big Test is active.\n* His Ultimate with the desert eagles, The Ban Hammer, taunts a targeted enemy with an icon that will damage them every time they miss an attack; while Deadpool gains bonus health and healing over time. The player even gains additional bonus health when the target misses.\n** When upgraded, the enemy will also take additional damage every second.\n* His Ultimate with the katanas, The Big Test, grants speed, healing over time, bonus health for allies, and intiating a challenge for Deadpool to land Bunny Bounce or Hazardous Hijinx five times within 12s. Once he does, he lands the Jackpot; doubling speed, healing, and refreshing the cooldown of Healing Factor.\n** Hazardous Hijinx has all charges refreshed once the challenge is initiated.\n** When upgraded, Deadpool grants bonus health to himself and nearby allies by dealing damage with Jackpot active.\n\n==== Duelist ====\n* As a Duelist, Deadpool loses survivability and utility for raw damage output.\n* His secondary fire with the desert eagles, Headshot!, throws out his avatar icon out to spin in place for continous damage, then retract back to him.\n** When upgraded, Deadpool will throw his avatar three times total; causing it to explode on the last throw.\n** Upgrading this ability early-on is a great way to XP as quick as possible.\n* His secondary fire with the katanas is Hazardous Hijinx, which has two charges even without upgrades.\n** When upgraded, the ability can be chained an unlimited amount of times; bouncing after each hit.\n* Deadpool In Your Area grants 20% damage reduction to himself.\n* Bunny Hop can be reset by bouncing off a wall or enemy. Deadpool also gains bonus health when doing so.\n* His Ultimate with the desert eagles, Skill Issue, taunts an enemy to suffer damage for every attack they miss.\n** When upgraded, the enemy will take additional damage every second and be inflicted with a stack of Vulnerability on each missed attack (10% per stack, up to 4 stacks).\n* His Ultimate with the katanas, Pop Quiz!, grants speed, healing over time, and initiates a challenge for Deadpool to land Bunny Hop or Hazardous Hijinx seven times within 12s. Once he does, he receives double the speed and healing from landing the Jackpot.\n** When upgraded, Deadpool also gains a 15% damage boost that doubles when he completes the challenge.\n** Landing the Jackpot will also reset all cooldowns except for his Healing Factor.\n\n==== Strategist ====\n* As a Strategist, Deadpool exchanges offensive capabilities for healing and team support.\n* Dual Desert Eagles can heal allies, while Kick@$$ Katanas heals nearby allies after every hit.\n** When upgraded, the explosive projectile from his desert eagles also heals allies caught in the blast.\n* His secondary fire with the desert eagles, Bouncing Bobblehead, is the same as Headshot except the avatar icon also heals allies - both whilst spinning and on the explosion.\n** Upgrading this ability early-on is a great way to XP as quick as possible.\n* His secondary fire with the katanas, Healing Hijinx, is a short dash attack that heals nearby allies on impact.\n** When upgraded, Deadpool can chain the dash up to three total times. He also bounces after each hit.\n* Deadpool In Your Area heals those nearby while active.\n** When upgraded, the healing/damage is increased while allies gain a damage boost.\n* Healing Hop restores health for allies you bounce off of, resetting the cooldown.\n* His Ultimate with the desert eagles, Pwnage Pound, is the same taunt that grants healing over time on activation and additional healing for each attack missed.\n** When upgraded, the target suffers extra damage every second.\n* His Ultimate with the katanas, Final Exam, applies healing over time and initiates a challenge for Deadpool to land Healing Hop, Healing Hijinx, or Bouncing Bobblehead eight times within 12s. Once he does, he lands the Jackpot and earns greater healing.\n** When upgraded, landing the Jackpot grants bonus health and refreshes the Healing Factor cooldown.\n\n=== Weaknesses ===\n* If Deadpool is defeated, his style gauge is reset to rank E, even if he reached rank S and charged his Ultimate. This means that he''s the only character in the game that can lose his Ultimate once charged.\n* While Deadpool charges his Ultimate faster than other heroes, it does have a cooldown of 60 seconds after each use. This makes his Ultimates favor frequency over effectiveness.\n* As a Vanguard, Deadpool struggles to gain XP the most between his two other roles.\n* As a Duelist, his utility can often feel outclassed by the Vanguard role.\n** Upgraded Hazardous Hijinx will also not begin to recharge until Deadpool misses a dash.\n* As a Strategist, he heavily relies upon his team to support him while his Ultimate is active to make large plays.\n\n==Costumes==\n{{COSMETICS - Deadpool Costumes}}\n\n==Abilities==\n{{Abilities/Deadpool}}\n\n==Strategy==\n{{Section stub}}\n\n==Personality==\n{| style=\"border: none;\"\n| [[File:Deadpool - Deadpool Nameplate Table Icon.png|110x110px]]\n| {{Quote|It''s Deadpool time, kiddos! Let''s F$#%$% go!|{{Audio|Deadpool - Hero Spawned 05.ogg}} Deadpool}}\n|}\n  \nDeadpool, the Merc with a Mouth, is widely renowned as the mercenary with a warped sense of humor and a deep self-awareness, as seen by continuous, irreverent jokes, sardonic wit, energetic behavior and his ability of fourth-wall breaking. This irreverence makes him appear unserious, hiding a deeper pain and the absurdity of his existence and his mental instability caused by his healing factor. He is frequently shown as a flirtatious, bubbly, chaotic and anti-heroic, but ultimately compassionate individual who cares deeply. Wade, unlike other heroes, understands that he is a fictional character, which drives his sarcasm, unpredictable behavior, and refusal to follow societal norms. He frequently taunts, jokes and belittles his opponents for his own amusement. He also has no shame and can create a comedy out of any circumstance, even if it does not go his way. Wade is described as the ultimate loudmouth because he speaks continually, obsessively, and frequently without filter or pause. His dirty mouth is faster than his brain, spouting curse words, pop-culture references, memes, insults, meta commentary, and adult jokes even during battles. Silence makes him uneasy, so he fills every second with noise, jokes, and meandering monologues, regardless of who is listening. \n\nAs a mercenary and anti-hero, Wade accepts jobs for money, revenge, or simple boredom, frequently switching sides if his feelings alter mid-mission. Unlike trained assassins, he fights brutally and chaotically while constantly talking, taunting enemies and using unpredictability as a tactical advantage. His violence is extreme and dramatic, but it is not mindless; he understands combat and knows how far to push a situation in order to survive.  He resides in the gray area between kindness and selfishness. He does not believe in being \"good\" in the traditional sense, but he consistently chooses to protect the innocent, particularly when he detects vulnerability or pain in himself. His actions are frequently vulgar, harsh, and morally ambiguous, but they are motivated by emotional devotion rather than abstract justice.   \n\nHis interactions with other heroes are chaotic, inconsistent, and deeply revealing, highlighting the conflict between how he acts and who he truly wants to be. From great admiration and friendship to frustration and outright dislike. With [[Wolverine]], they have a complex, frequently hostile, but eventually strong friendship transitioning from enemies who continually conflict to reluctant allies forced to work together. They are complete opposites: Logan is moody and stern, while Wade is loud and humorous, resulting in a typical odd pair interaction characterized by frustration and mocking combined with real affection and respect. Now with his connection with [[Spider-Man]], their banter is frequent, but beyond the jokes, Deadpool really desires Spider-Man''s approval because it would imply that someone truly nice can accept him. While Wade''s aggression and lack of boundaries frequently disturb and annoyed Peter, he still regards him as a human and friend. Additionally, Wade genuinely cares for the ones he love and his allies and one example is [[Jeff the Land Shark]], as he loves and cares for him treating as his lovable son.\n\nOverall, Deadpool is a tragic, humorous, flirtatious, and a loudmouth who laughs, fights, and speaks incessantly in order to endure, all while longing for significance and intimacy in a world that has left him damaged yet unkillable. He yaps because there are times he craves attention, connection, and recognition, even if it takes the shape of eye rolls, signs of annoyance or warnings to shut him up. He keeps speaking loudly and constantly even to us; as long as he''s yapping, he lives, and being aware as a fictional character in a comic book, video game or movie, giving us amusement. \n\n==Achievements==\nSee: [[Achievements]]\n{| class=\"fandom-table\" width=\"100%\"\n! style=\"background:#484e75; color:white;\" |<font size=\"3\"><span style=\"font-family: Refrigerator Deluxe Regular;\">''''''ICONS''''''</span></font>\n! style=\"background:#484e75; color:white; width:80%;\" |<font size=\"3\"><span style=\"font-family: Refrigerator Deluxe Regular;\">''''''ACHIEVEMENTS''''''</span></font>\n! style=\"background:#484e75; color:white; width:7%;\" |<font size=\"3\"><span style=\"font-family: Refrigerator Deluxe Regular;\">''''''POINTS''''''</span></font>\n|-\n| style=\"background:#e1e6ec; color:black;\" |[[File:AchIcon Heroic Journey Silver.png|70px]]\n| style=\"background:#e1e6ec; color:black;\" |''''''Say \"Chimichanga!\"''''''<br>As Deadpool, take pics with 3 KO''d enemies in a single match.\n| style=\"background:#e1e6ec; color:#747681;\" |<center>[[File:Achievement Star Icon.png|alt=Achievement Points|30x30px|Points]]<br>''''''10''''''</center>\n|-\n| style=\"background:#e1e6ec; color:black;\" |[[File:AchIcon Heroic Journey Bronze.png|70px]]\n| style=\"background:#e1e6ec; color:black;\" |''''''Custody Battle''''''<br>As Deadpool, take down an enemy Emma Frost.\n| style=\"background:#e1e6ec; color:#747681;\" |<center>[[File:Achievement Star Icon.png|alt=Achievement Points|30x30px|Points]]<br>''''''5''''''</center>\n|}\n\n\n==Proficiency Challenges==\n=== Challenges ===\n{{Hero Proficiency/Tab|Deadpool}}\n\n=== Rewards ===\n{{Proficiency Rewards|Deadpool}}\n\n==Gallery==\n<tabber>\nPromotional=\n<gallery>\nDeadpool is coming to Marvel Rivals on Jan 16 -- Season 6- Night at the Museum Official Trailer\nDeadpool Hero Reveal.jpg|Deadpool Hero Card\nDeadpool from Season 6 Trailer.png|Deadpool in the \"[[Season 6: Night at the Museum]]\" Official Trailer\nSeason 6 Night at the Museum.png|Deadpool in Season 6''s promotional image\n</gallery>\n|-|In-Game Assets=\n<gallery>\nDeadpool Hero Logo.png|Hero Logo\nDeadpool Story.png|Hero Story Artwork\nAccessory Icon - Deadpool Plush.png|Deadpool as [[Jeff the Land Shark|Jeff]]''s Plush [[Accessories|Accessory]]\nNameplate - MARVEL SNAP Deadpool Nameplate.png|Deadpool as a MARVEL Snap promotional [[Nameplates|Nameplate]]\nSpray Icon - Marvel''s Deadpool VR.png|[[File:Rare Skin Rarity Icon.png|20px|link=]] ''''''Marvel''s Deadpool VR'''''' \n</gallery>\n|-|Gallery Card=\n<gallery>\nGallery Card Love is a Battlefield - Museum Security.png|Deadpool and [[Elsa Bloodstone]] (silhouettes) in \"Museum Security\".\nGallery Card - One Night At The Museum.png|Deadpool—alongside [[Rogue]], [[Gambit]] and the [[Collector]]—in \"One Night at the Museum\".\nGallery Card - The True Monster.png|Deadpool (among other characters) in \"The True Monster\".\nGallery Card - The Ballad Of Wade Wilson.png|Deadpool, [[Elsa Bloodstone]] and a [[Brood Queen]] in \"The Ballad of Wade Wilson\".\nGallery Card - The New Marauders.png|Deadpool (among other characters) in \"The New Marauders\".\nGallery Card - There An'' Back Again.png|Deadpool attending [[Rogue]] and [[Gambit]]''s wedding in \"There An'' Back Again\".\nGallery Card - Monsters Take Manhattan.png|Deadpool (alongside his monstrous subjects) in \"Monsters Take Manhattan\".\n</gallery>\n</tabber>\n{{Clr}}\n\n\n==Trivia==\n<tabber>\nGeneral & History=\n*Deadpool''s first appearance was in [[w:c:Marvel:New_Mutants_Vol_1_98|''''\"The New Mutants\"'''' (1990) #98]] in December 1990.\n*Deadpool is voiced by [[Alejandro Saab]], best known for his role as Gabimaru in ''''Hell''s Paradise'''', as well Akihiko Sanada in ''''Persona 3 Reload'''' and Cyno in ''''Genshin Impact''''.\n*Deadpool was datamined from multiple sources around December 2024, along with 15 other characters, including [[Angela]], [[Blade]], [[Captain Marvel]], [[Emma Frost]], [[Hit-Monkey]], [[Human Torch]], [[Invisible Woman]], [[Mister Fantastic]], [[M.O.D.O.K.]], [[Phoenix]], [[The Hood]], [[The Thing]], [[Ultron]], and [[Valkyrie]].<ref name=\"leak\">{{Cite web |url=https://thegamepost.com/all-marvel-rivals-leaks-characters-maps-modes/ |title=All Marvel Rivals Leaks: All 15 Characters, 5 Maps, Team-Ups, Game Modes, And More |publisher=The Game Post |date=December 31, 2024}}</ref>\n*He appears as a plush accessory for [[Jeff the Land Shark]] and a nameplate promoting ''''MARVEL Snap''''.\n*Deadpool was speculated to make his debut in Season 6 alongside [[Elsa Bloodstone]] due to a gallery card in [[Season 5: Love is a Battlefield]] teasing the theme of both characters quoting \"a blathering, foul-mouthed mercenary and a monster hunter as deadly as she is beautiful.\"\n**A silhouette of Deadpool can be seen on the cover art of the ''Museum Security'' gallery card for [[Season 5: Love is a Battlefield]].\n*In the [[Season 6: Night at the Museum]] Trailer, Deadpool opens with \"What''s up, Game Awards?!\" in the Game Awards trailer, and \"What''s up, gamers?!\" in the official trailer.\n*During the [[Season 5: Love is a Battlefield|Season 5.5]] update, Deadpool was revealed early in-game as a Duelist in the hero roster, but is locked.\n**He appeared in every player''s Strike Squad, a feature which allows you to pre-select heroes that you prefer to use in matches.\n**After the Version 20251218 Patch, his role was changed to Vanguard, having originally been listed as a Duelist. Additionally he was removed from the strike squad.\n**After the Version 20251225 Patch, his role was changed to Strategist, after previously being listed as Duelist and Vanguard.\n**After the Version 20260101 Patch, his role was changed to a question mark and was also removed from the hero select screen, becoming only viewable on the Heroes page.\n**These teasers hint at Deadpool''s multi-role abilities, making him the first hero to play all three key roles in the game.\n*To announce his arrival in [[Season 6: Night at the Museum|Season 6.0]], Deadpool appeared in [https://www.youtube.com/watch?v=rmU6RtypJ3w ''''Dev Vision Vol. 13''''], where his in-game 3D model was animated to interrupt developer Guangguang. This fourth-wall-breaking moment was used to introduce him as the game''s first multi-role hero, marking a unique departure from the typical announcement format.\n**As a prelude to the video, a [https://x.com/MarvelRivals/status/2011105965215744325?s=20 social media teaser] was released an hour before ''''Dev Vision Vol. 13.'''' It featured the previously known Season 6 promotional image where the in-game 3D model of Deadpool suddenly \"came to life\", physically pulling aside the background of the illustration to reveal the ''''Dev Vision'''' set while asking for his official announcement.\n**Deadpool''s debut in the Night in the Museum season could be a nod to director Shaun Levy, known for the Night at the Museum movies and the director of Deadpool & Wolverine.\n*Deadpool is currently the only masked playable character who has never been seen unmasked in ''''[[Marvel Rivals]]''''.\n\n|-|\nVisuals=\n*The promotional image for Season 6 shows Deadpool doing a ''''Sailor Moon'''' pose.\n*The main promotional art of Season 6 references the painting \"Liberty Leading the People\" by Eugène Delacroix, with Deadpool''s pose imitating Liberty.\n*In the [[Season 6: Night at the Museum]] Official Trailer, Deadpool destroys a Sentinel by spinning inside its arm. This is most likely a reference to Levi''s spin attack against the Beast Titan from ''''Attack on Titan''''.\n*Also in the Season 6 trailer, Deadpool can be seen posing and moonwalking referencing moves by popular singer and dancer Michael Jackson.\n*When upgrading the \"Dual Desert Eagles\" ability, Deadpool’s pistols turn gold. While this is a visual indicator specific to his upgraded weapons, many players have noted the resemblance to the \"gold-plated .50 caliber Desert Eagle pistoleros\" used by the Nicepool variant in the 2024 film ''''Deadpool & Wolverine''''.\n\n|-|\nQuotes=\n*In his classic 4th wall breaking, Deadpool has plenty of lines and interactions with other heroes referencing pop culture and internet memes.\n*Though censored, Deadpool is the first hero to drop an f-bomb in Marvel Rivals, which first appeared in his hero reveal video.\n*[[Alejandro Saab|Alejandro]] can be heard breaking character at the end in one of Deadpool''s small talk lines which is \"Here comes Wade! Here comes Wade! Fightin'' jerks, and gettin'' paid! [sung]\".\n*Upon respawning, Deadpool may say \"Sigh, you sent us back to spawn? Weak...\". The beginning of the line is delivered in a way that sounds like \"CyYu\", a phonetic nod to the VTuber persona of Deadpool’s voice actor, Alejandro Saab.\n*During the pre-round phase, Deadpool mentions an \"afterparty in the Bats Mobile.\" While the name may be a pun on the famous DC vehicle, it actually refers to the Strange Academy school bus featured as the payload in the [[Museum of Contemplation]] map.\n**Deadpool \"borrowed\" this bus to transport various multiversal creatures to the [[Collector|Collector''s]] Museum under the guise of saving them from the [[Timestream Entanglement]]. The vehicle''s name is a tribute to [[Bats]], [[Doctor Strange|Doctor Strange''s]] ghost dog.\n*When pinging that his Ultimate is 100% charged, Deadpool exclaims \"I''m ready! Are you...?\". The high-pitched delivery of the first half is a nod to ''''SpongeBob SquarePants'''' and his iconic catchphrase. This also serves as a meta-reference to the character''s history, as SpongeBob’s voice actor, ''''Tom Kenny'''', previously voiced Deadpool in the game ''''Marvel Super Hero Squad Online''''.\n*When upgrading the \"Dual Desert Eagles\" ability, Deadpool exclaims \"I''m feeling trigger happy!\", which could be a reference to the name of one of his signature special attacks in the ''''Marvel vs. Capcom'''' series.\n*When using his Duelist Ultimate \"Skill Issue\", he shouts \"What are you aiming at?!\". This is a reference to a viral ''''Counter-Strike'''' (''''CS:GO'''') clip by streamer ''''Steel_TV'''', who famously rages while spectating a teammate missing shots on an enemy standing directly in front of him.\n*When Deadpool respawns he will say \"Ah $#%$%, here we go again...\", which refers to a famous cutscene of Carl \"CJ\" Johnson from the 2004 video game ''''Grand Theft Auto: San Andreas''''.\n*After taking down an enemy, one of Deadpool lines is \"May the force be with you\", referencing ''''Star Wars''''.\n*When using the ability \"Magical Unicorn Shield!\", he says \"You can''t handle the cute!\" which references the 1992 film ''''A Few Good Men.'''' The famous line is \"You can''t handle the truth!\" delivered by Jack Nicholson as Colonel Jessup.\n**Other line Deadpool may say when using this ability is \"Unicorn, I choose you!\" which references the ''''Pokémon'''' franchise.\n*When Deadpool uses the ability \"Headshot!\" he may say \"Here comes Headpool!\". This is a direct reference to the ''''Headpool'''' character variant: a disembodied, sentient head of an alternate-universe Deadpool from the ''''Marvel Zombies'''' series.\n*If the player manages to do a penta-kill, Deadpool may say \"Five? What''s next? Six, seven?\", a meme originated from the song \"Doot Doot (6 7)\" by American rapper Skrilla.\n*Upon achieving an Ace (eliminating the entire enemy team), Deadpool sings \"Gotta cap ''em all!\". This is a parody of the iconic \"Gotta catch ''em all!\" catchphrase and theme song from the ''''Pokémon'''' animated show.\n*One of Deadpool''s abilities is called \"Deadpool in your area\". This is likely a reference to the Korean girl-group ''''BLACKPINK'''', as the character is a big fan of this musical genre, as implied in one of his interactions with [[Luna Snow]].\n**One of the voicelines of this ability is \"Go Deadpool! It''s your birthday!\", where Deadpool references the hit song ''''In Da Club'''' by American rapper ''''50 Cent'''', which starts by saying: \"Go shawty, it''s your birthday.\"\n**Another voiceline of this ability is \"I''m the best there is! Suck it, Logan!\", referencing Wolverine''s iconic line.\n**While using this ability, Deadpool can also say the line \"Everyone''s gettin'' DP''ed tonight!\", which is a ''''double entendre''''. While the initials \"DP\" primarily stand for his own name, the phrasing is a suggestive play on words referring to a specific adult sexual term that shares the same acronym.\n*When picking up a health-pack, Deadpool says \"Health? Aw, I wanted a fire flower\" in thick Italian accent. This is a clear reference to the ''''Super Mario Bros'''' series.\n**Deadpool can jump over the heads of allies or enemies in a \"Goomba-like\" fashion. When doing so, he occasionally shouts \"Yoo-hoo!\", which is a direct vocal nod to Mario’s iconic exclamation when jumping or performing stunts.\n*Deadpool refers to [[Doctor Strange|Doctor Strange''s]] portals as \"Marvel sparkle circles\" in some of his lines. This is a reference to the way the character calls these portals in the ''''Deadpool & Wolverine'''' movie.\n*There is a secret easter egg voiceline on the [[K''un-Lun: Heart of Heaven|Heart of Heaven]] map, where Deadpool exclaims \"All right, stairway to heaven! Talk about a classic!\", which is a reference to the iconic 1971 song ''''Stairway to Heaven'''' by the band ''''Led Zeppelin.''''\n*When entering the [[Empire of Eternal Night: Midtown|Midtown]] map, Deadpool''s line about joining the [[Avengers]] or becoming their part-time janitor is a nod to his long-standing desire to join the team. It specifically references the 2024 film ''''Deadpool & Wolverine'''', where he interviews for a position with Happy Hogan.\n**In this same map, Deadpool can be heard saying \"No... sleep... ''til Midtown! Seriously?\", which is a musical nod to the 1986 song ''''No Sleep ''til Brooklyn'''' by the ''''Beastie Boys''''. The line replaces the original borough from the lyrics with the map''s location.\n*Upon entering the [[Hydra Charteris Base|Charteris Base]] map, Deadpool jokes about their slogan begging people to cut their arms off. This is a humorous take on the organization''s official motto: \"Cut off one head, two more shall take its place\", highlighting the irony of a recruitment cry that encourages dismemberment.\n*While escorting the payload in [[Empire of Eternal Night: Central Park|Central Park]], Deadpool may refer to [[Ratatoskr]] as \"Ratatouille\" in one of his lines. This is a play on the phonetic similarity between the names and a direct reference to the Disney-Pixar film ''''Ratatouille.''''\n*While escorting the Knull''s Essence on the [[Klyntar: Symbiotic Surface|Symbiotic Surface]] map, Deadpool asks, \"Wow, when did Hot Topic get its own planet?\". This is a reference to the retail chain ''''Hot Topic'''', known for its dark, alternative, and \"edgy\" aesthetic, which Deadpool humorously compares to the symbiote-covered environment of the map.\n*While escorting the payload in the [[Intergalactic Empire of Wakanda: Hall of Djalia|Hall of Djalia]], Deadpool can say, \"We gotta move fast, like panthers! Not slow, like Garfield!\". This is a humorous contrast between the [[Black Panther|Black Panthers]] of Wakanda and the famous comic strip cat Garfield, known for his laziness.\n*When pinging the payload as part of the defending team, Deadpool may exclaim \"They shall not pass!\". This is a direct reference to the iconic line spoken by Gandalf in J.R.R. Tolkien’s ''''The Lord of the Rings: The Fellowship of the Ring''''.\n*When Deadpools destroys [[Rocket Raccoon|Rocket''s]] B.R.B., Deadpool sings \"You''re welcome!\". This is a musical nod to the song ''''You''re Welcome'''' performed by Maui (Dwayne Johnson) in the 2016 Disney film ''''Moana.''''\n*Upon seeing [[Peni Parker|Peni Parker''s]] nests, Deadpool may say \"Spider-Bots. Why''d it have to be Spider-Bots?\". This is a parody of the famous line spoken by ''''Indiana Jones'''' (Harrison Ford) in the 1981 film ''''Raiders of the Lost Ark'''': \"Snakes. Why did it have to be snakes?\"\n*When encountering one of [[Namor|Namor''s]] squids, Deadpool may sing \"Attack of the killer sushi!\" in an ominous, macabre tone. This is a parody of the theme song from the 1978 cult classic horror-comedy film ''''Attack of the Killer Tomatoes.''''\n*If Deadpool detects a sniper character, he will say \"My sniper-sense is tingling!\", a reference to Spider-Man''s spider-sense.\n**Upon eliminating an enemy sniper, Deadpool may shout \"Sniper, no sniping!\" in a high-pitched voice. This is a parody of the recurring line \"Swiper, no swiping!\" from the children''s animated series ''''Dora the Explorer''''.\n*When receiving a damage boost, Deadpool can say \"Eat your heart out, Colossus\" while imitating a heavy Russian accent. This is a direct nod to his often comedic relationship with the X-Man [[Colossus]].\n*During his small talk lines, Deadpool says, \"Ugh. What the hell is Tiger Division, and why do they keep calling me?\". This is a reference to South Korea''s national superhero team in the Marvel Universe.\n**The joke is particularly relevant to ''''Marvel Rivals'''' as the team features Luna Snow, and alludes to rumors regarding the future inclusion of [[White Fox]], the leader of said team.\n*During the pre-round phase, Deadpool jokes about upcoming roster additions by saying, \"Spoiler alert: Next season''s characters are Speedball and Sleepwalker. Leak that, losers!\". This is a meta-reference to the frequent community leaks surrounding the game, while specifically naming two \"cult classic\" Marvel characters as a way to mock the credibility of online leakers.\n*In one of his small talk dialogues, Deadpool expresses a desire to show Vanessa \"what she''s missing\" now that he is a hero in ''''Marvel Rivals''''. While trying to impress her, he makes a meta-commentary acknowledging that the game exists in a \"different continuity\" from the comics and the MCU—the latter being where she is his primary love interest, whereas in the comics she is also known as the shapeshifter Copycat.\n*Occasionally during a game, Deadpool hums or whistles various tunes and melodies. These include:\n**''''Rivals ''Til the End'''' and ''''Shining Star'''', both original songs composed for the game and performed by singer Chrissy Costanza.\n**The game''s Highlight theme.\n**The final part of the MCU fanfare.\n\n|-|\nHero Interactions=\n*When talking to [[Moon Knight]], Deadpool will mention that he reminds him of a guy he once teamed up with, who had a sweet cape, fancy gadgets, grim demeanor and long pointy ears. This is a reference to Batman from DC Comics, and their crossover published in September 2025: [[w:c:Marvel:Marvel/DC:_Deadpool/Batman_Vol 1_1|''''\"Marvel/DC: Deadpool/Batman\" (2025) #1]].\n**When [[Moon Knight]] throws an Ankh, Deadpool may exclaim, \"That symbol! It''s the artist formerly known as Moon Knight!\". This is a reference to the musician ''''Prince'''', who in 1993 changed his stage name to an unpronounceable symbol similar to an Ankh, leading the media to refer to him as \"The Artist Formerly Known as Prince\".\n*When talking to [[Namor]], Deadpool will acknowledge the character''s status as \"Marvel''s first super-hero\". He will also reference DC''s Aquaman, by saying that Namor beat \"the other fish guy\" by two years, since Namor made his first appearance in 1939 and Aquaman in 1941.\n*If Deadpool eliminates Wolverine, he will say the phrase \"May the claws be with you,\" a variation of the famous quote \"May the Force be with you\" from the Star Wars franchise.\n*When talking to [[Peni Parker]], Deadpool asks if SP//dr is an EVA Unit or a baby Gundam, referencing ''''Neon Genesis Evangelion'''' and ''''Mobile Suit Gundam'''', respectively.\n*In a dialogue with [[Angela]], Deadpool''s heavy emphasis on the word \"fantasies\" and Angela''s response about them being his \"final\" ones is likely a reference to the ''''Final Fantasy'''' series. This is specifically a nod to the character Sephiroth, since both characters are depicted as \"One-Winged Angels\".\n*When speaking to [[Spider-Man]], Deadpool’s line \"It''s morbin'' time!\" refers to the popular meme surrounding the 2022 film ''''Morbius''''. The phrase became a famous fake quote that fans pretended was in the movie, despite it never actually being said.\n**Deadpool calling Morbius \"Hollywood gold\" is rather sarcastic, since the movie is a box-office bomb.\n*When speaking to [[Hawkeye]], Deadpool says: \"Try livin'' on the edge, arrowsmith!\", which is a play on words referencing the band ''''Aerosmith'''' and their 1993 hit song ''''Livin'' on the Edge''''.\n**Deadpool also refers to Hawkeye as \"Hawk-tuah\" in one of his lines, a play on words referencing a viral social media catchphrase and soundbite that became an internet meme in 2024.\n*When speaking to [[Storm]], Deadpool asks if she can \"bless the rains down in Africa\". This is a direct reference to the lyrics of the 1982 hit song ''''Africa'''' by the band ''''Toto'''', humorously connecting Storm''s powers as a weather goddess and her African heritage to the track. He additionally adds that \"It''s gonna take a lot to drag me away from you!\", further quoting the lyrics of the song.\n*When [[Wolverine]] denies being his partner, Deadpool tells him to check the international box-office, referencing the massive commercial success of the 2024 film ''''Deadpool & Wolverine'''', which saw the two characters team-up as protagonists.\n**In a similar vein, when Deadpool mentions they have to wait \"''til at least Phase 7\" for a sequel, he is referring to the MCU''s organizational structure. As the MCU was in Phase 6 when the character released, Deadpool is joking about the long wait for a potential follow-up to their 2024 film.\n*When talking to [[Loki]], Deadpool mentions the TVA and asks about \"his old pal Mobius\". This is a meta-reference to the MCU, specifically the ''''Loki'''' series and the film ''''Deadpool & Wolverine'''', where both characters have significant ties to the Time Variance Authority.\n*When Loki is wearing the [[Lady Loki (Costume)|Lady Loki]] skin, Deadpool will ask if they are enjoying it. This is a meta-commentary on the fact that \"Lady Loki\" was the first skin in ''''Marvel Rivals'''' to feature a complete gender swap, including an entirely new model and voice acting. Deadpool’s line also playfully acknowledges the community’s highly positive reception toward the skin’s visual design.\n**In a similar vein, Deadpool has a line wondering what his next cosmetic might be, excitedly mentioning how beautiful he would look in a Ladypool skin. This serves as a reference to his own female counterpart from the Deadpool Corps, as well as her prominent appearance in the 2024 film ''''Deadpool & Wolverine''''.\n*When talking to [[Magik]], Deadpool''s line \"Just ask Kevin!\" is likely a reference to Kevin Feige, the head of Marvel Studios.\n*When speaking to [[Scarlet Witch]], Deadpool mentions her \"sitcom with the Vision\". This is a reference to the Disney+ series ''''WandaVision'''', which emulated various classic and modern sitcom formats.\n*When interacting with [[Star-Lord]], Deadpool laments being stuck with him out of all the \"hot Chrises in the MCU\". This is a meta-reference to the three famous actors named Chris in the Marvel Cinematic Universe: Chris Pratt (Star-Lord), Chris Evans (Captain America), and Chris Hemsworth (Thor).\n*In one interaction with [[Captain America]], Deadpool’s dialogue about Cap Wolf and the Howling Commandos is a reference to Captain America’s legendary [[Capwolf|\"Capwolf\"]] skin.\n**This refers to a 1992 storyline starting in [[w:c:Marvel:Captain_America_Vol_1_402|''''\"Captain America\"'''' (1968) #402]], where Steve Rogers was transformed into a werewolf.\n**The Howling Commandos mentioned are a specialized S.H.I.E.L.D. unit composed of supernatural monsters, a team Capwolf has famously led in various comic book iterations.\n*In another interaction with [[Captain America]], Deadpool refers to him as \"Old Glory\". This is a famous patriotic nickname for the flag of the United States, and its use serves as a nod to Steve Rogers'' identity as a living symbol of the nation.\n*When speaking with [[Blade]], Deadpool asks him about a \"bloody rave\" to which he can invite [[Minor Characters#Shiklah|Shiklah]] on a date. This is a reference to the iconic opening scene of the 1998 Blade film. The visual and musical identity established in that film, ever since associated with Blade, is reflected in ''''Marvel Rivals'''' through the techno music that plays during his ultimate ability.\n**In the same interaction, Deadpool''s suggestion to go \"ice skating\" instead is a nod to a Blade’s famous line originated in the same film series, which has been associated with the character in various media ever since.\n*During his interaction with [[Adam Warlock]], he mentions an online hater named \"DeadpoolSuckz1990\". The numbers at the end are a nod to the character''s real-world history, as 1990 marks the year Deadpool made his first comic book appearance, as stated above.\n**In this same interaction, Deadpool’s joke about K''un-Lun hosting the Oscars is a reference to Adam’s golden appearance.\n</tabber>\n\n==References==\n{{Reflist}}\n==Navigation==\n{{Nav Heroes}}\n[[Category:Male Characters]]\n[[Category:Heroes]]\n[[Category:X-Men]]\n[[Category:Vanguards]]\n[[Category:Duelists]]\n[[Category:Strategists]]\n[[Category:Multi-Role]]\n[[Category:Mutants]]\n[[Category:X-Force]]\n[[Category:0-Star Difficulty]]\n[[Category:Anchor Hero]]\n[[Category:Mutates]]\n[[Category:Villains]]"}}}'::jsonb, '2026-06-15T12:09:07.114Z'::timestamptz, 'success', null),
  ('fandom-deadpool-abilities-template', 'Marvel Rivals Fandom Deadpool Ability Template', 'https://marvelrivals.fandom.com/api.php?action=parse&page=Template:Abilities/Deadpool&prop=wikitext&format=json&origin=*', '{"parse":{"title":"Template:Abilities/Deadpool","pageid":33763,"wikitext":{"*":"{{#tag:tabber|\nVanguard=\n{{#tag:tabber|\nDesert Eagles=\n{{SkillTable|Abilities/Deadpool/Vanguard/Guns}}\n{{!}}-{{!}}\nKatanas=\n{{SkillTable|Abilities/Deadpool/Vanguard/Swords}}\n{{!}}-{{!}}\nAbility Upgrades=\n{{SkillTable|Abilities/Deadpool/Vanguard/Ability Upgrades}}\n{{!}}-{{!}}\n}}\n{{!}}-{{!}}\nDuelist=\n{{#tag:tabber|\nDesert Eagles=\n{{SkillTable|Abilities/Deadpool/Duelist/Guns}}\n{{!}}-{{!}}\nKatanas=\n{{SkillTable|Abilities/Deadpool/Duelist/Swords}}\n{{!}}-{{!}}\nAbility Upgrades=\n{{SkillTable|Abilities/Deadpool/Duelist/Ability Upgrades}}\n{{!}}-{{!}}\n}}\n{{!}}-{{!}}\nStrategist=\n{{#tag:tabber|\nDesert Eagles=\n{{SkillTable|Abilities/Deadpool/Strategist/Guns}}\n{{!}}-{{!}}\nKatanas=\n{{SkillTable|Abilities/Deadpool/Strategist/Swords}}\n{{!}}-{{!}}\nAbility Upgrades=\n{{SkillTable|Abilities/Deadpool/Strategist/Ability Upgrades}}\n{{!}}-{{!}}\n}}\n{{!}}-{{!}}\n}}\n<noinclude>\n[[Category:Ability Templates]]\n</noinclude>"}}}'::jsonb, '2026-06-15T12:09:07.405Z'::timestamptz, 'success', null),
  ('steam-marvel-rivals-news', 'Steam Marvel Rivals News', 'https://api.steampowered.com/ISteamNews/GetNewsForApp/v2/?appid=2767030&count=8&maxlength=1200&format=json', '{"appnews":{"appid":2767030,"newsitems":[{"gid":"1835871199303083","title":"Marvel Rivals Version 20260618 Patch Notes","url":"https://steamstore-a.akamaihd.net/news/externalpost/steam_community_announcements/1835871199303083","is_external_url":true,"author":"Marvel Rivals","contents":"Greetings, Rivals!We''re thrilled to announce the upcoming patch drops on June 18th, 2026, at 09 : 00 : 00 (UTC)! No server downtime; just patch and play!Here''s what''s coming your way: All-New ContentRivals Summer Festival Arrives!Even Earth''s Mightiest Heroes need a beach day! This summer, take a break from the Chronoverse clashes and join us at Hellfire Bay Beach for a refreshing, picture-perfect vacay! During your stay, complete festive events and exclusive missions to claim abundant FREE rewards, including Mister Fantastic - Fantastic Beach Bod costume, 2,500 Units, an exclusive Title, and more! Massive New Social Hub: Hellfire Bay BeachThis week introduces an entirely new social map: Hellfire Bay Beach. You can access it via the Krakoan flower portal in Times Square or straight from the Rivals Summer Festival interface.In this new hub, beyond just taking in the stunning scenery of the Krakoan beach, you can drink up some of Cyclops'' X-Press Juice, enjoy Fishing, join the Tandem Tides event, take Summer Snapshots with friends, grab a Pym-ini Sandwich, and browse or purchase the brand-new Swimsuit Special costumes. Additionally, a new series of water traversal Emotes will let you...","feedlabel":"Community Announcements","date":1781765181,"feedname":"steam_community_announcements","feed_type":1,"appid":2767030},{"gid":"1835236783559764","title":"Marvel Rivals: Dive Into Season 8.5 // Dev Vision Vol. 18","url":"https://steamstore-a.akamaihd.net/news/externalpost/steam_community_announcements/1835236783559764","is_external_url":true,"author":"Marvel Rivals","contents":"Guangguang is back, and he''s here to welcome you all to Season 8.5 of Marvel Rivals! 🌟 Dive into all the latest upcoming content with Guangguang as he dishes out new changes, a brand-new map, the newest hero, and so much more. Tune in now to get a sneak peek at exciting new features arriving on June 12th!","feedlabel":"Community Announcements","date":1781169736,"feedname":"steam_community_announcements","feed_type":1,"appid":2767030},{"gid":"1835236783559763","title":"Marvel Rivals Version 20260612 Patch Notes - Season 8.5 Arrives","url":"https://steamstore-a.akamaihd.net/news/externalpost/steam_community_announcements/1835236783559763","is_external_url":true,"author":"Marvel Rivals","contents":"Greetings, Rivals!Welcome to Marvel Rivals Season 8.5! Get ready to turn up the heat as we proudly welcome the return of the Summers!We''ll be taking the servers offline for a quick tune-up starting on June 12, 2026, at 09 : 00 (UTC). Maintenance should last for approximately 2 hours.Grab your shades (or visor) and dive into the patch notes to see what''s making waves this update! All-New ContentNew HeroTo me, my X-Men! Cyclops officially arrives on the Marvel Rivals battlefield! New MapAfter a long delay, the legendary Tournament of the Heavenly Cities has officially commenced! Following a grueling series of preliminaries, the Immortal Weapons have reached the finals to test their might and mind. Prepare to step onto the sacred martial grounds! The all-new Bounty Annihilation (18 VS.18) game mode map, K''un-Lun: Shenloong Arena, is here!Note: Due to performance limitations, this new map mode is temporarily unavailable on Xbox Series S. New Stories- New Cyclops Lore - Clear Eyes, Full Hearts - New Daredevil Lore - Clearing the Path - New The Punisher Lore - One Last Shot New In Store- Magik - Soulless Sword Bundle - Cyclops - Weapon M Bundle - Phoenix - White Crown Phoenix Bundle - Cy...","feedlabel":"Community Announcements","date":1781169731,"feedname":"steam_community_announcements","feed_type":1,"appid":2767030},{"gid":"1835236783558307","title":"Marvel Rivals Version 20260612 Balance Post","url":"https://steamstore-a.akamaihd.net/news/externalpost/steam_community_announcements/1835236783558307","is_external_url":true,"author":"Marvel Rivals","contents":"The Timestream is in flux once again, and the battlefield is getting a cosmic recalibration! The prehistoric fury of Devil Dinosaur has been tempered, and we''re reining in the long-range poke from Star-Lord and Phoenix. Meanwhile, brawlers like Rogue and Blade are getting the green light to get up close and personal! From the depths of Atlantis to the far reaches of the cosmos, here''s everything you need to know about the latest balance shifts! ADJUSTMENTSVANGUARDAngelaAsgard''s Assassin is now swifter and sturdier than ever! Angela''s survivability and mobility get a slight boost. - Reduce Assassin''s Charge cooldown from 6s to 4s. - In Shielded Stance, increase shield value from 300 to 350. Upon canceling the shield, increase shield recovery rate from 50/s to 60/s. Reduce the interval between shield uses from 1.5s to 1s.Devil DinosaurLooks like Moon Girl needs to put her big buddy on a slight diet! We''re slightly reducing Devil Dinosaur''s damage, survivability, and crowd control to balance the experience for other Vanguards facing him. - Remove the knock-down effect from Impact Beam. - Increase Buddy Barrier cooldown from 10s to 12s. - Reduce the Percentage Damage per second of the ...","feedlabel":"Community Announcements","date":1781113474,"feedname":"steam_community_announcements","feed_type":1,"appid":2767030},{"gid":"1834602721186662","title":"Marvel Rivals Version 20260604 Patch Notes","url":"https://steamstore-a.akamaihd.net/news/externalpost/steam_community_announcements/1834602721186662","is_external_url":true,"author":"Marvel Rivals","contents":"Greetings, Rivals!We''re thrilled to announce the upcoming patch drops on June 4th, 2026, at 09 : 00 : 00 (UTC)! No server downtime; just patch and play!Here''s what''s coming your way: All-New ContentNew In StoreMantis - Mandy Celestine: The Greeter Bundle Limited Time: June 5th, 2026, 02 : 00 : 00 to July 3rd 2026, 02 : 00 : 00 (UTC) Iron Man - Iron Samurai Bundle Iron Samurai Emoji Bundle Available From: June 5th, 2026, at 02 : 00 : 00 (UTC) Fixes and OptimizationsHeroes1. Black Cat''s Aquatic Blind Spot: Fixed a rather bizarre interaction where if Black Cat and a teammate were gobbled up by Jeff the Land Shark''s Ultimate Ability, her active Faltine Flame Orb would lose its Reveal effect. Cats may hate the water, but Felicia''s mystic surveillance is now fully waterproof!  2. Rogue''s Force-Field Friction: Resolved a kinetic anomaly where Rogue''s Team-Up Ability, Hearts as One, would occasionally fail to deal its intended explosive damage if the kinetic blast collided with the Invisible Woman''s force shield. Sue Storm is tough, but Rogue''s Southern hospitality will now properly blast those around the shield as intended!Other1. S.H.I.E.L.D. Encryption Secured: Fixed a UI bug where the ...","feedlabel":"Community Announcements","date":1780554315,"feedname":"steam_community_announcements","feed_type":1,"appid":2767030},{"gid":"1833968530887665","title":"Victims of cheaters in Marvel Rivals will be refunded all the ranked points they lost if they report them thanks to NetEase''s new Anti-Cheat Rank Compensation System","url":"https://steamstore-a.akamaihd.net/news/externalpost/PC Gamer/1833968530887665","is_external_url":true,"author":"Elie Gould","contents":"Being surprised at seeing cheating in online competitive multiplayer games is like being surprised at seeing a fish in the ocean, you''re going to encounter some every now and then, that''s just how it goes. But <a href=\"https://www.pcgamer.com/marvel-rivals/https://www.pcgamer.com/marvel-rivals/\">Marvel Rivals</a> has had a particularly rough time with cheaters as of late. To stretch out the above analogy as far as it''ll go, it feels like the salmon rush right now... <a href=\"https://www.pcgamer.com/games/third-person-shooter/victims-of-cheaters-in-marvel-rivals-will-be-refunded-all-the-ranked-points-they-lost-if-they-report-them-thanks-to-neteases-new-anti-cheat-rank-compensation-system/?utm_source=steam&utm_medium=referral\" target=\"_blank\">Read more.</a>","feedlabel":"PC Gamer","date":1779962755,"feedname":"PC Gamer","feed_type":0,"appid":2767030},{"gid":"1833968530887233","title":"Marvel Rivals Version 20260528 Patch Notes","url":"https://steamstore-a.akamaihd.net/news/externalpost/steam_community_announcements/1833968530887233","is_external_url":true,"author":"Marvel Rivals","contents":"Greetings, Rivals!We''re thrilled to announce the upcoming patch drops on May 28th, 2026, at 09 : 00 : 00 (UTC)! No server downtime; just patch and play!Here''s what''s coming your way: All-New ContentNew Map: Alchemax HeadquartersWelcome to Nueva York, 2099! Alchemax is the mega-corporation holding a ruthless monopoly over the future. Armed with cutting-edge tech, they''ve been secretly conducting a series of mad, classified experiments behind closed doors. To put an end to their timeline Incursion once and for all, Devil Dinosaur smashes into Alchemax Headquarters, carrying a portable TRD (Timestream Reintegration Device), dragging the corporation''s darkest secrets into the light! Watch your step, corporate espionage just got prehistoric. Map Mode: Doom Match Event: Chrono-RushThe TVA is working overtime! The Chrono-Rush event kicks off this weekend. Play matches and rack up Chrono Tokens, with no cap on how many points you can earn! The more you play, the more you get!Event Schedule: 2026/5/29, 12 : 00 : 00 - 2026/6/1, 12 : 00 : 00 (UTC) 2026/6/5, 12 : 00 : 00 - 2026/6/8, 12 : 00 : 00 (UTC) 2026/6/12, 12 : 00 : 00 - 2026/6/15, 12 : 00 : 00 (UTC) 2026/6/19, 12 : 00 : 00 - 2026/6/22, ...","feedlabel":"Community Announcements","date":1779949371,"feedname":"steam_community_announcements","feed_type":1,"appid":2767030},{"gid":"1833334318579940","title":"Marvel Rivals has banned 485 accounts and dished out just 3 hardware bans after the latest slew of cheaters but players are begging for more","url":"https://steamstore-a.akamaihd.net/news/externalpost/PC Gamer/1833334318579940","is_external_url":true,"author":"Elie Gould","contents":"It''s been a bad weekend for <a href=\"https://www.pcgamer.com/marvel-rivals/\">Marvel Rivals</a> after a small update opened the floodgates for more cheaters to scurry inside, wreaking havoc in games all the way from Bronze to One Above All. How bad is it you ask? A slew of cheaters actually took to streaming their crimes over the weekend to a sizeable audience, promoting their software, and dunking on high elo players. So yeah, pretty bad... <a href=\"https://www.pcgamer.com/games/third-person-shooter/marvel-rivals-has-banned-485-accounts-and-dished-out-just-3-hardware-bans-after-the-latest-slew-of-cheaters-but-players-are-begging-for-more/?utm_source=steam&utm_medium=referral\" target=\"_blank\">Read more.</a>","feedlabel":"PC Gamer","date":1779815101,"feedname":"PC Gamer","feed_type":0,"appid":2767030}],"count":331}}'::jsonb, '2026-06-20T08:01:45.423Z'::timestamptz, 'success', null)
